1	//! Port of `chipbot-controller.ts` (Chipbot cached-audio routes).
2	
3	use std::ffi::OsString;
4	use std::path::{Path as FsPath, PathBuf};
5	use std::time::{Duration, SystemTime, UNIX_EPOCH};
6	
7	use axum::extract::{Extension, Path, State};
8	use axum::http::{header, HeaderMap};
9	use axum::response::{IntoResponse, Response};
10	use futures_util::StreamExt;
11	use id3::{Tag, TagLike, Version};
12	use tokio::io::AsyncWriteExt;
13	use url::Url;
14	
15	use crate::audio::disk::{
16	    audio_content_type, is_audio_extension, normalize_isrc, validate_directory, validate_file,
17	    AUDIO_EXTENSIONS,
18	};
19	use crate::audio::range::{file_response, parse_range};
20	use crate::cache::manifest::{self, FileManifestEntry};
21	use crate::clients::TrackCounterSource;
22	use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
23	use crate::providers::chipbot::ChipbotTrack;
24	use crate::state::AppState;
25	use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};
26	
27	const CHIPBOT_FETCH_TIMEOUT_MS: u64 = 15_000;
28	
29	#[derive(Debug)]
30	struct FileRequestValidation {
31	    isrc: Option<String>,
32	    requested_format: String,
33	    errors: ResultEnvelope<()>,
34	}
35	
36	fn requested_extension(raw_format: &str) -> String {
37	    if raw_format.starts_with('.') {
38	        raw_format.to_string()
39	    } else {
40	        format!(".{raw_format}")
41	    }
42	}
43	
44	fn validate_file_request(raw_isrc: &str, raw_format: &str) -> FileRequestValidation {
45	    let isrc = normalize_isrc(raw_isrc);
46	    let requested_format = requested_extension(raw_format);
47	    let mut errors = ResultEnvelope::<()>::new();
48	
49	    if isrc.is_none() {
50	        errors.add_error(
51	            &ApiError::new(
52	                "Valid ISRC is required",
53	                ErrorType::Validation,
54	                ErrorContext::Api,
55	            )
56	            .with_status(400),
57	        );
58	    }
59	    if !is_audio_extension(&requested_format) {
60	        errors.add_error(
61	            &ApiError::new(
62	                "Invalid track format",
63	                ErrorType::Validation,
64	                ErrorContext::Api,
65	            )
66	            .with_status(400),
67	        );
68	    }
69	
70	    FileRequestValidation {
71	        isrc,
72	        requested_format,
73	        errors,
74	    }
75	}
76	
77	fn cache_filename(isrc: &str, extension: &str) -> Option<String> {
78	    let isrc = normalize_isrc(isrc)?;
79	    is_audio_extension(extension).then(|| format!("{isrc}{extension}"))
80	}
81	
82	fn manifest_filename(isrc: &str, extension: &str) -> Option<String> {
83	    cache_filename(isrc, extension).map(|filename| format!("tmp-chipbot/{filename}"))
84	}
85	
86	fn audio_extension_from_url(url: &Url) -> Option<&'static str> {
87	    let path = url.path();
88	    let requested = match path.rfind('.') {
89	        Some(dot) if dot + 1 < path.len() => &path[dot..],
90	        _ => ".mp3",
91	    };
92	    AUDIO_EXTENSIONS
93	        .iter()
94	        .copied()
95	        .find(|extension| *extension == requested)
96	}
97	
98	fn allowed_audio_url(raw: &str) -> Option<Url> {
99	    let url = Url::parse(raw).ok()?;
100	    matches!(url.scheme(), "http" | "https").then_some(url)
101	}
102	
103	fn tmp_path_for(path: &FsPath) -> PathBuf {
104	    let mut tmp = OsString::from(path.as_os_str());
105	    tmp.push(".tmp");
106	    PathBuf::from(tmp)
107	}
108	
109	fn now_ms() -> i64 {
110	    SystemTime::now()
111	        .duration_since(UNIX_EPOCH)
112	        .map(|duration| duration.as_millis().min(i64::MAX as u128) as i64)
113	        .unwrap_or(0)
114	}
115	
116	fn error_response(
117	    message: impl Into<String>,
118	    error_type: ErrorType,
119	    status: u16,
120	    cause: Option<String>,
121	) -> Response {
122	    let mut error = ApiError::new(message, error_type, ErrorContext::Api).with_status(status);
123	    if let Some(cause) = cause {
124	        error = error.with_cause(cause);
125	    }
126	    let mut result = ResultEnvelope::<()>::new();
127	    result.add_error(&error);
128	    result.into_response()
129	}
130	
131	fn not_found_response(message: String) -> Response {
132	    error_response(message, ErrorType::Unknown, 404, None)
133	}
134	
135	fn internal_error_response(cause: String) -> Response {
136	    error_response(
137	        "Internal server error",
138	        ErrorType::Internal,
139	        500,
140	        Some(cause),
141	    )
142	}
143	
144	async fn audio_file_response(
145	    path: &FsPath,
146	    extension: &str,
147	    headers: &HeaderMap,
148	) -> Result<Response, String> {
149	    let metadata = tokio::fs::metadata(path)
150	        .await
151	        .map_err(|error| format!("stat cached Chipbot file: {error}"))?;
152	    let range = headers
153	        .get(header::RANGE)
154	        .map(|value| value.to_str().unwrap_or(""));
155	    let outcome = parse_range(range, metadata.len());
156	    Ok(file_response(
157	        path,
158	        metadata.len(),
159	        outcome,
160	        audio_content_type(extension),
161	        HeaderMap::new(),
162	    )
163	    .await)
164	}
165	
166	async fn send_cached_chipbot_track(
167	    state: &AppState,
168	    headers: &HeaderMap,
169	    isrc: &str,
170	    bw: Option<&BandwidthOp>,
171	) -> Result<Option<Response>, String> {
172	    for extension in AUDIO_EXTENSIONS {
173	        let Some(path) = state.disk.chipbot_cache_path(isrc, extension) else {
174	            continue;
175	        };
176	        if !validate_file(&path).await {
177	            continue;
178	        }
179	
180	        tracing::info!(
181	            target: "CHIPBOT",
182	            isrc,
183	            extension,
184	            origin = "chipbot",
185	            "audio source: CHIPBOT fs cache"
186	        );
187	        if let Some(op) = bw {
188	            op.set_provider(BandwidthProvider::Chipbot);
189	            op.mark_cache(CacheMark::Hit);
190	        }
191	        return audio_file_response(&path, extension, headers)
192	            .await
193	            .map(Some);
194	    }
195	    Ok(None)
196	}
197	
198	fn write_chipbot_id3(path: &FsPath, isrc: &str, origin_url: &str) -> Result<(), id3::Error> {
199	    let mut tag = Tag::new();
200	    tag.add_frame(id3::frame::Comment {
201	        lang: "eng".to_string(),
202	        description: String::new(),
203	        text: origin_url.to_string(),
204	    });
205	    for (description, value) in [
206	        ("source", "chipbot"),
207	        ("isrc", isrc),
208	        ("origin_url", origin_url),
209	    ] {
210	        tag.add_frame(id3::frame::ExtendedText {
211	            description: description.to_string(),
212	            value: value.to_string(),
213	        });
214	    }
215	    tag.write_to_path(path, Version::Id3v23)
216	}
217	
218	async fn cache_chipbot_track(
219	    state: &AppState,
220	    track: &ChipbotTrack,
221	    isrc: &str,
222	    bw: Option<&BandwidthOp>,
223	) -> Result<Option<PathBuf>, String> {
224	    let Some(audio) = track.audio.as_ref().filter(|audio| !audio.url.is_empty()) else {
225	        return Ok(None);
226	    };
227	    let Some(url) = allowed_audio_url(&audio.url) else {
228	        return Ok(None);
229	    };
230	    let Some(extension) = audio_extension_from_url(&url) else {
231	        return Ok(None);
232	    };
233	    let Some(file_path) = state.disk.chipbot_cache_path(isrc, extension) else {
234	        return Ok(None);
235	    };
236	
237	    validate_directory(&state.disk.chipbot)
238	        .await
239	        .map_err(|error| format!("create Chipbot cache directory: {error}"))?;
240	
241	    if let Some(op) = bw {
242	        op.add_upstream_requests(1);
243	    }
244	    let request = state.http.get(url).header(header::ACCEPT, "*/*");
245	    let response = tokio::time::timeout(
246	        Duration::from_millis(CHIPBOT_FETCH_TIMEOUT_MS),
247	        request.send(),
248	    )
249	    .await
250	    .map_err(|_| "This operation was aborted".to_string())?
251	    .map_err(|error| format!("Chipbot audio fetch failed: {error}"))?;
252	    if let (Some(op), Some(bytes)) = (bw, response.content_length().filter(|bytes| *bytes > 0)) {
253	        op.add_upstream_received(bytes);
254	    }
255	    if !response.status().is_success() {
256	        return Err(format!(
257	            "Chipbot audio fetch failed: HTTP {}",
258	            response.status().as_u16()
259	        ));
260	    }
261	
262	    let tmp_path = tmp_path_for(&file_path);
263	    let stream_result: Result<(), String> = async {
264	        let mut file = tokio::fs::File::create(&tmp_path)
265	            .await
266	            .map_err(|error| format!("create Chipbot temp file: {error}"))?;
267	        let mut stream = response.bytes_stream();
268	        while let Some(chunk) = stream.next().await {
269	            let chunk = chunk.map_err(|error| format!("read Chipbot audio stream: {error}"))?;
270	            file.write_all(&chunk)
271	                .await
272	                .map_err(|error| format!("write Chipbot temp file: {error}"))?;
273	        }
274	        file.flush()
275	            .await
276	            .map_err(|error| format!("flush Chipbot temp file: {error}"))?;
277	        drop(file);
278	        tokio::fs::rename(&tmp_path, &file_path)
279	            .await
280	            .map_err(|error| format!("rename Chipbot cache file: {error}"))?;
281	        Ok(())
282	    }
283	    .await;
284	    if let Err(error) = stream_result {
285	        let _ = tokio::fs::remove_file(&tmp_path).await;
286	        return Err(error);
287	    }
288	
289	    if extension == ".mp3" {
290	        let tag_path = file_path.clone();
291	        let tag_isrc = isrc.to_string();
292	        let origin_url = audio.url.clone();
293	        match tokio::task::spawn_blocking(move || {
294	            write_chipbot_id3(&tag_path, &tag_isrc, &origin_url)
295	        })
296	        .await
297	        {
298	            Ok(Ok(())) => {}
299	            Ok(Err(error)) => tracing::warn!(
300	                target: "CHIPBOT",
301	                isrc,
302	                error = %error,
303	                "Failed to write Chipbot ID3 tags"
304	            ),
305	            Err(error) => tracing::warn!(
306	                target: "CHIPBOT",
307	                isrc,
308	                error = %error,
309	                "Failed to write Chipbot ID3 tags"
310	            ),
311	        }
312	    }
313	
314	    let size = tokio::fs::metadata(&file_path)
315	        .await
316	        .map_err(|error| format!("stat downloaded Chipbot file: {error}"))?
317	        .len();
318	    let manifest_name = manifest_filename(isrc, extension)
319	        .ok_or_else(|| "invalid Chipbot manifest filename".to_string())?;
320	    manifest::set_entry(
321	        &state.redis,
322	        &manifest_name,
323	        &FileManifestEntry {
324	            source: Some("chipbot".to_string()),
325	            isrc: Some(isrc.to_string()),
326	            size: Some(size),
327	            cached_at: Some(now_ms()),
328	            ..Default::default()
329	        },
330	    )
331	    .await
332	    .map_err(|error| format!("write Chipbot file manifest: {error}"))?;
333	
334	    Ok(Some(file_path))
335	}
336	
337	async fn get_track_file_by_isrc_inner(
338	    state: &AppState,
339	    raw_isrc: String,
340	    raw_format: String,
341	    headers: &HeaderMap,
342	    bw: Option<&BandwidthOp>,
343	) -> Result<Response, String> {
344	    let FileRequestValidation {
345	        isrc,
346	        requested_format,
347	        errors,
348	    } = validate_file_request(&raw_isrc, &raw_format);
349	    tracing::debug!(
350	        target: "CHIPBOT",
351	        isrc = ?isrc,
352	        raw_isrc,
353	        raw_format,
354	        requested_format,
355	        range = ?headers.get(header::RANGE),
356	        "getTrackFileByIsrc controller input"
357	    );
358	    if errors.has_errors {
359	        return Ok(errors.into_response());
360	    }
361	    let isrc = isrc.expect("validated ISRC");
362	
363	    if let Some(response) = send_cached_chipbot_track(state, headers, &isrc, bw).await? {
364	        return Ok(response);
365	    }
366	
367	    let track = state.chipbot.get_track_by_isrc(&isrc, bw).await;
368	    tracing::debug!(
369	        target: "CHIPBOT",
370	        isrc,
371	        found = track.is_some(),
372	        has_audio = track
373	            .as_ref()
374	            .and_then(|track| track.audio.as_ref())
375	            .is_some_and(|audio| !audio.url.is_empty()),
376	        "getTrackFileByIsrc chipbot lookup result"
377	    );
378	    if let Some(track) = track {
379	        if let Some(file_path) = cache_chipbot_track(state, &track, &isrc, bw).await? {
380	            tracing::info!(
381	                target: "CHIPBOT",
382	                isrc,
383	                origin = "chipbot",
384	                "audio source: CHIPBOT API (downloaded + cached)"
385	            );
386	            if let Some(op) = bw {
387	                op.set_provider(BandwidthProvider::Chipbot);
388	                op.mark_cache(CacheMark::Miss);
389	            }
390	            // Fire-and-forget: the handle is a spawned task, deliberately detached.
391	            drop(
392	                state
393	                    .api_db
394	                    .fire_and_forget_track_counter(TrackCounterSource::Chipbot),
395	            );
396	            let extension = file_path
397	                .extension()
398	                .and_then(|extension| extension.to_str())
399	                .map(|extension| format!(".{extension}"))
400	                .unwrap_or_else(|| ".mp3".to_string());
401	            return audio_file_response(&file_path, &extension, headers).await;
402	        }
403	    }
404	
405	    Ok(not_found_response(format!(
406	        "Track file not found on Chipbot [isrc: {isrc}]"
407	    )))
408	}
409	
410	/// `getTrackFileByIsrcHandler` — downloads on cache miss.
411	pub async fn get_track_file_by_isrc(
412	    State(state): State<AppState>,
413	    Path((raw_isrc, raw_format)): Path<(String, String)>,
414	    headers: HeaderMap,
415	    bw: Option<Extension<BandwidthOp>>,
416	) -> Response {
417	    let bw = bw.as_ref().map(|extension| &extension.0);
418	    match get_track_file_by_isrc_inner(&state, raw_isrc, raw_format, &headers, bw).await {
419	        Ok(response) => response,
420	        Err(error) => {
421	            tracing::error!(
422	                target: "CHIPBOT",
423	                error,
424	                "ChipbotController - getTrackFileByIsrc"
425	            );
426	            internal_error_response(error)
427	        }
428	    }
429	}
430	
431	/// `GET /chipbot/tracks/{isrc}/file` — format omitted, defaults to mp3.
432	pub async fn get_track_file_by_isrc_default(
433	    State(state): State<AppState>,
434	    Path(raw_isrc): Path<String>,
435	    headers: HeaderMap,
436	    bw: Option<Extension<BandwidthOp>>,
437	) -> Response {
438	    let bw = bw.as_ref().map(|extension| &extension.0);
439	    match get_track_file_by_isrc_inner(&state, raw_isrc, "mp3".to_string(), &headers, bw).await {
440	        Ok(response) => response,
441	        Err(error) => {
442	            tracing::error!(
443	                target: "CHIPBOT",
444	                error,
445	                "ChipbotController - getTrackFileByIsrcDefault"
446	            );
447	            internal_error_response(error)
448	        }
449	    }
450	}
451	
452	async fn get_track_file_only_cache_by_isrc_inner(
453	    state: &AppState,
454	    raw_isrc: String,
455	    raw_format: String,
456	    headers: &HeaderMap,
457	    bw: Option<&BandwidthOp>,
458	) -> Result<Response, String> {
459	    let FileRequestValidation {
460	        isrc,
461	        requested_format: _,
462	        errors,
463	    } = validate_file_request(&raw_isrc, &raw_format);
464	    tracing::debug!(
465	        target: "CHIPBOT",
466	        isrc = ?isrc,
467	        raw_isrc,
468	        raw_format,
469	        range = ?headers.get(header::RANGE),
470	        "getTrackFileOnlyCacheByIsrc controller input"
471	    );
472	    if errors.has_errors {
473	        return Ok(errors.into_response());
474	    }
