477	    if let Some(response) = send_cached_chipbot_track(state, headers, &isrc, bw).await? {
478	        return Ok(response);
479	    }
480	
481	    Ok(not_found_response(format!(
482	        "Track file not found in Chipbot cache [isrc: {isrc}]"
483	    )))
484	}
