486	/// `getTrackFileOnlyCacheByIsrcHandler` — never calls Chipbot upstream.
487	pub async fn get_track_file_only_cache_by_isrc(
488	    State(state): State<AppState>,
489	    Path((raw_isrc, raw_format)): Path<(String, String)>,
490	    headers: HeaderMap,
491	    bw: Option<Extension<BandwidthOp>>,
492	) -> Response {
