494	    match get_track_file_only_cache_by_isrc_inner(&state, raw_isrc, raw_format, &headers, bw).await
495	    {
496	        Ok(response) => response,
497	        Err(error) => {
498	            tracing::error!(
499	                target: "CHIPBOT",
