508	/// `GET /chipbot/tracks/{isrc}/file/only-cache` — format omitted, defaults to mp3.
509	pub async fn get_track_file_only_cache_by_isrc_default(
510	    State(state): State<AppState>,
511	    Path(raw_isrc): Path<String>,
512	    headers: HeaderMap,
513	    bw: Option<Extension<BandwidthOp>>,
514	) -> Response {
515	    let bw = bw.as_ref().map(|extension| &extension.0);
516	    match get_track_file_only_cache_by_isrc_inner(&state, raw_isrc, "mp3".to_string(), &headers, bw)
517	        .await
518	    {
519	        Ok(response) => response,
520	        Err(error) => {
521	            tracing::error!(
522	                target: "CHIPBOT",
523	                error,
524	                "ChipbotController - getTrackFileOnlyCacheByIsrcDefault"
525	            );
526	            internal_error_response(error)
527	        }
528	    }
