531	#[cfg(test)]
532	mod tests {
533	    use super::*;
534	
535	    #[test]
536	    fn validation_normalizes_isrc_and_accepts_all_ts_formats() {
537	        for format in ["mp3", ".webm", "flac", ".ogg", "m4a", ".wav"] {
538	            let validation = validate_file_request(" usrc17607839 ", format);
539	            assert!(!validation.errors.has_errors, "{format}");
540	            assert_eq!(validation.isrc.as_deref(), Some("USRC17607839"));
541	            assert!(is_audio_extension(&validation.requested_format));
542	        }
543	    }
544	
545	    #[test]
546	    fn validation_accumulates_isrc_and_format_errors() {
547	        let validation = validate_file_request("not-an-isrc", "AAC");
548	        assert!(validation.errors.has_errors);
549	        assert_eq!(validation.errors.status_code, 400);
550	        assert_eq!(validation.errors.errors.len(), 2);
551	        assert_eq!(
552	            validation.errors.errors[0].message,
553	            "Valid ISRC is required"
554	        );
555	        assert_eq!(validation.errors.errors[1].message, "Invalid track format");
556	        assert!(
557	            validate_file_request("USRC17607839", "MP3")
558	                .errors
559	                .has_errors
560	        );
561	    }
562	
563	    #[test]
564	    fn filename_and_manifest_mapping_are_safe_and_normalized() {
565	        assert_eq!(
566	            cache_filename(" usrc17607839 ", ".m4a").as_deref(),
567	            Some("USRC17607839.m4a")
568	        );
569	        assert_eq!(
570	            manifest_filename("usrc17607839", ".mp3").as_deref(),
571	            Some("tmp-chipbot/USRC17607839.mp3")
572	        );
573	        assert_eq!(cache_filename("../escape", ".mp3"), None);
574	        assert_eq!(cache_filename("USRC17607839", ".aac"), None);
575	    }
576	
577	    #[test]
578	    fn audio_url_extension_mapping_matches_ts_fallback() {
579	        assert_eq!(
580	            audio_extension_from_url(&Url::parse("https://cdn.test/song.flac?x=1").unwrap()),
581	            Some(".flac")
582	        );
583	        assert_eq!(
584	            audio_extension_from_url(&Url::parse("https://cdn.test/song").unwrap()),
585	            Some(".mp3")
586	        );
587	        assert_eq!(
588	            audio_extension_from_url(&Url::parse("https://cdn.test/song.aac").unwrap()),
589	            None
590	        );
591	        assert_eq!(
592	            audio_extension_from_url(&Url::parse("https://cdn.test/song.MP3").unwrap()),
593	            None
594	        );
595	        assert!(allowed_audio_url("ftp://cdn.test/song.mp3").is_none());
596	        assert!(allowed_audio_url("https://cdn.test/song.mp3").is_some());
597	    }
598	}
