//! Port of `chipbot-controller.ts` (Chipbot cached-audio routes).

use std::ffi::OsString;
use std::path::{Path as FsPath, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use axum::extract::{Extension, Path, State};
use axum::http::{header, HeaderMap};
use axum::response::{IntoResponse, Response};
use futures_util::StreamExt;
use id3::{Tag, TagLike, Version};
use tokio::io::AsyncWriteExt;
use url::Url;

use crate::audio::disk::{
    audio_content_type, is_audio_extension, normalize_isrc, validate_directory, validate_file,
    AUDIO_EXTENSIONS,
};
use crate::audio::range::{file_response, parse_range};
use crate::cache::manifest::{self, FileManifestEntry};
use crate::clients::TrackCounterSource;
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::providers::chipbot::ChipbotTrack;
use crate::state::AppState;
use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};

const CHIPBOT_FETCH_TIMEOUT_MS: u64 = 15_000;

#[derive(Debug)]
struct FileRequestValidation {
    isrc: Option<String>,
    requested_format: String,
    errors: ResultEnvelope<()>,
}

fn requested_extension(raw_format: &str) -> String {
    if raw_format.starts_with('.') {
        raw_format.to_string()
    } else {
        format!(".{raw_format}")
    }
}

fn validate_file_request(raw_isrc: &str, raw_format: &str) -> FileRequestValidation {
    let isrc = normalize_isrc(raw_isrc);
    let requested_format = requested_extension(raw_format);
    let mut errors = ResultEnvelope::<()>::new();

    if isrc.is_none() {
        errors.add_error(
            &ApiError::new(
                "Valid ISRC is required",
                ErrorType::Validation,
                ErrorContext::Api,
            )
            .with_status(400),
        );
    }
    if !is_audio_extension(&requested_format) {
        errors.add_error(
            &ApiError::new(
                "Invalid track format",
                ErrorType::Validation,
                ErrorContext::Api,
            )
            .with_status(400),
        );
    }

    FileRequestValidation {
        isrc,
        requested_format,
        errors,
    }
}

fn cache_filename(isrc: &str, extension: &str) -> Option<String> {
    let isrc = normalize_isrc(isrc)?;
    is_audio_extension(extension).then(|| format!("{isrc}{extension}"))
}

fn manifest_filename(isrc: &str, extension: &str) -> Option<String> {
    cache_filename(isrc, extension).map(|filename| format!("tmp-chipbot/{filename}"))
}

fn audio_extension_from_url(url: &Url) -> Option<&'static str> {
    let path = url.path();
    let requested = match path.rfind('.') {
        Some(dot) if dot + 1 < path.len() => &path[dot..],
        _ => ".mp3",
    };
    AUDIO_EXTENSIONS
        .iter()
        .copied()
        .find(|extension| *extension == requested)
}

fn allowed_audio_url(raw: &str) -> Option<Url> {
    let url = Url::parse(raw).ok()?;
    matches!(url.scheme(), "http" | "https").then_some(url)
}

fn tmp_path_for(path: &FsPath) -> PathBuf {
    let mut tmp = OsString::from(path.as_os_str());
    tmp.push(".tmp");
    PathBuf::from(tmp)
}

fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().min(i64::MAX as u128) as i64)
        .unwrap_or(0)
}

fn error_response(
    message: impl Into<String>,
    error_type: ErrorType,
    status: u16,
    cause: Option<String>,
) -> Response {
    let mut error = ApiError::new(message, error_type, ErrorContext::Api).with_status(status);
    if let Some(cause) = cause {
        error = error.with_cause(cause);
    }
    let mut result = ResultEnvelope::<()>::new();
    result.add_error(&error);
    result.into_response()
}

fn not_found_response(message: String) -> Response {
    error_response(message, ErrorType::Unknown, 404, None)
}

fn internal_error_response(cause: String) -> Response {
    error_response(
        "Internal server error",
        ErrorType::Internal,
        500,
        Some(cause),
    )
}

async fn audio_file_response(
    path: &FsPath,
    extension: &str,
    headers: &HeaderMap,
) -> Result<Response, String> {
    let metadata = tokio::fs::metadata(path)
        .await
        .map_err(|error| format!("stat cached Chipbot file: {error}"))?;
    let range = headers
        .get(header::RANGE)
        .map(|value| value.to_str().unwrap_or(""));
    let outcome = parse_range(range, metadata.len());
    Ok(file_response(
        path,
        metadata.len(),
        outcome,
        audio_content_type(extension),
        HeaderMap::new(),
    )
    .await)
}

async fn send_cached_chipbot_track(
    state: &AppState,
    headers: &HeaderMap,
    isrc: &str,
    bw: Option<&BandwidthOp>,
) -> Result<Option<Response>, String> {
    for extension in AUDIO_EXTENSIONS {
        let Some(path) = state.disk.chipbot_cache_path(isrc, extension) else {
            continue;
        };
        if !validate_file(&path).await {
            continue;
        }

        tracing::info!(
            target: "CHIPBOT",
            isrc,
            extension,
            origin = "chipbot",
            "audio source: CHIPBOT fs cache"
        );
        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Chipbot);
            op.mark_cache(CacheMark::Hit);
        }
        return audio_file_response(&path, extension, headers)
            .await
            .map(Some);
    }
    Ok(None)
}

fn write_chipbot_id3(path: &FsPath, isrc: &str, origin_url: &str) -> Result<(), id3::Error> {
    let mut tag = Tag::new();
    tag.add_frame(id3::frame::Comment {
        lang: "eng".to_string(),
        description: String::new(),
        text: origin_url.to_string(),
    });
    for (description, value) in [
        ("source", "chipbot"),
        ("isrc", isrc),
        ("origin_url", origin_url),
    ] {
        tag.add_frame(id3::frame::ExtendedText {
            description: description.to_string(),
            value: value.to_string(),
        });
    }
    tag.write_to_path(path, Version::Id3v23)
}

async fn cache_chipbot_track(
    state: &AppState,
    track: &ChipbotTrack,
    isrc: &str,
    bw: Option<&BandwidthOp>,
) -> Result<Option<PathBuf>, String> {
    let Some(audio) = track.audio.as_ref().filter(|audio| !audio.url.is_empty()) else {
        return Ok(None);
    };
    let Some(url) = allowed_audio_url(&audio.url) else {
        return Ok(None);
    };
    let Some(extension) = audio_extension_from_url(&url) else {
        return Ok(None);
    };
    let Some(file_path) = state.disk.chipbot_cache_path(isrc, extension) else {
        return Ok(None);
    };

    validate_directory(&state.disk.chipbot)
        .await
        .map_err(|error| format!("create Chipbot cache directory: {error}"))?;

    if let Some(op) = bw {
        op.add_upstream_requests(1);
    }
    let request = state.http.get(url).header(header::ACCEPT, "*/*");
    let response = tokio::time::timeout(
        Duration::from_millis(CHIPBOT_FETCH_TIMEOUT_MS),
        request.send(),
    )
    .await
    .map_err(|_| "This operation was aborted".to_string())?
    .map_err(|error| format!("Chipbot audio fetch failed: {error}"))?;
    if let (Some(op), Some(bytes)) = (bw, response.content_length().filter(|bytes| *bytes > 0)) {
        op.add_upstream_received(bytes);
    }
    if !response.status().is_success() {
        return Err(format!(
            "Chipbot audio fetch failed: HTTP {}",
            response.status().as_u16()
        ));
    }

    let tmp_path = tmp_path_for(&file_path);
    let stream_result: Result<(), String> = async {
        let mut file = tokio::fs::File::create(&tmp_path)
            .await
            .map_err(|error| format!("create Chipbot temp file: {error}"))?;
        let mut stream = response.bytes_stream();
        while let Some(chunk) = stream.next().await {
            let chunk = chunk.map_err(|error| format!("read Chipbot audio stream: {error}"))?;
            file.write_all(&chunk)
                .await
                .map_err(|error| format!("write Chipbot temp file: {error}"))?;
        }
        file.flush()
            .await
            .map_err(|error| format!("flush Chipbot temp file: {error}"))?;
        drop(file);
        tokio::fs::rename(&tmp_path, &file_path)
            .await
            .map_err(|error| format!("rename Chipbot cache file: {error}"))?;
        Ok(())
    }
    .await;
    if let Err(error) = stream_result {
        let _ = tokio::fs::remove_file(&tmp_path).await;
        return Err(error);
    }

    if extension == ".mp3" {
        let tag_path = file_path.clone();
        let tag_isrc = isrc.to_string();
        let origin_url = audio.url.clone();
        match tokio::task::spawn_blocking(move || {
            write_chipbot_id3(&tag_path, &tag_isrc, &origin_url)
        })
        .await
        {
            Ok(Ok(())) => {}
            Ok(Err(error)) => tracing::warn!(
                target: "CHIPBOT",
                isrc,
                error = %error,
                "Failed to write Chipbot ID3 tags"
            ),
            Err(error) => tracing::warn!(
                target: "CHIPBOT",
                isrc,
                error = %error,
                "Failed to write Chipbot ID3 tags"
            ),
        }
    }

    let size = tokio::fs::metadata(&file_path)
        .await
        .map_err(|error| format!("stat downloaded Chipbot file: {error}"))?
        .len();
    let manifest_name = manifest_filename(isrc, extension)
        .ok_or_else(|| "invalid Chipbot manifest filename".to_string())?;
    manifest::set_entry(
        &state.redis,
        &manifest_name,
        &FileManifestEntry {
            source: Some("chipbot".to_string()),
            isrc: Some(isrc.to_string()),
            size: Some(size),
            cached_at: Some(now_ms()),
            ..Default::default()
        },
    )
    .await
    .map_err(|error| format!("write Chipbot file manifest: {error}"))?;

    Ok(Some(file_path))
}

async fn get_track_file_by_isrc_inner(
    state: &AppState,
    raw_isrc: String,
    raw_format: String,
    headers: &HeaderMap,
    bw: Option<&BandwidthOp>,
) -> Result<Response, String> {
    let FileRequestValidation {
        isrc,
        requested_format,
        errors,
    } = validate_file_request(&raw_isrc, &raw_format);
    tracing::debug!(
        target: "CHIPBOT",
        isrc = ?isrc,
        raw_isrc,
        raw_format,
        requested_format,
        range = ?headers.get(header::RANGE),
        "getTrackFileByIsrc controller input"
    );
    if errors.has_errors {
        return Ok(errors.into_response());
    }
    let isrc = isrc.expect("validated ISRC");

    if let Some(response) = send_cached_chipbot_track(state, headers, &isrc, bw).await? {
        return Ok(response);
    }

    let track = state.chipbot.get_track_by_isrc(&isrc, bw).await;
    tracing::debug!(
        target: "CHIPBOT",
        isrc,
        found = track.is_some(),
        has_audio = track
            .as_ref()
            .and_then(|track| track.audio.as_ref())
            .is_some_and(|audio| !audio.url.is_empty()),
        "getTrackFileByIsrc chipbot lookup result"
    );
    if let Some(track) = track {
        if let Some(file_path) = cache_chipbot_track(state, &track, &isrc, bw).await? {
            tracing::info!(
                target: "CHIPBOT",
                isrc,
                origin = "chipbot",
                "audio source: CHIPBOT API (downloaded + cached)"
            );
            if let Some(op) = bw {
                op.set_provider(BandwidthProvider::Chipbot);
                op.mark_cache(CacheMark::Miss);
            }
            // Fire-and-forget: the handle is a spawned task, deliberately detached.
            drop(
                state
                    .api_db
                    .fire_and_forget_track_counter(TrackCounterSource::Chipbot),
            );
            let extension = file_path
                .extension()
                .and_then(|extension| extension.to_str())
                .map(|extension| format!(".{extension}"))
                .unwrap_or_else(|| ".mp3".to_string());
            return audio_file_response(&file_path, &extension, headers).await;
        }
    }

    Ok(not_found_response(format!(
        "Track file not found on Chipbot [isrc: {isrc}]"
    )))
}

/// `getTrackFileByIsrcHandler` — downloads on cache miss.
pub async fn get_track_file_by_isrc(
    State(state): State<AppState>,
    Path((raw_isrc, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match get_track_file_by_isrc_inner(&state, raw_isrc, raw_format, &headers, bw).await {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileByIsrc"
            );
            internal_error_response(error)
        }
    }
}

/// `GET /chipbot/tracks/{isrc}/file` — format omitted, defaults to mp3.
pub async fn get_track_file_by_isrc_default(
    State(state): State<AppState>,
    Path(raw_isrc): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match get_track_file_by_isrc_inner(&state, raw_isrc, "mp3".to_string(), &headers, bw).await {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileByIsrcDefault"
            );
            internal_error_response(error)
        }
    }
}

async fn get_track_file_only_cache_by_isrc_inner(
    state: &AppState,
    raw_isrc: String,
    raw_format: String,
    headers: &HeaderMap,
    bw: Option<&BandwidthOp>,
) -> Result<Response, String> {
    let FileRequestValidation {
        isrc,
        requested_format: _,
        errors,
    } = validate_file_request(&raw_isrc, &raw_format);
    tracing::debug!(
        target: "CHIPBOT",
        isrc = ?isrc,
        raw_isrc,
        raw_format,
        range = ?headers.get(header::RANGE),
        "getTrackFileOnlyCacheByIsrc controller input"
    );
    if errors.has_errors {
        return Ok(errors.into_response());
    }
    let isrc = isrc.expect("validated ISRC");

    if let Some(response) = send_cached_chipbot_track(state, headers, &isrc, bw).await? {
        return Ok(response);
    }

    Ok(not_found_response(format!(
        "Track file not found in Chipbot cache [isrc: {isrc}]"
    )))
}

/// `getTrackFileOnlyCacheByIsrcHandler` — never calls Chipbot upstream.
pub async fn get_track_file_only_cache_by_isrc(
    State(state): State<AppState>,
    Path((raw_isrc, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match get_track_file_only_cache_by_isrc_inner(&state, raw_isrc, raw_format, &headers, bw).await
    {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileOnlyCacheByIsrc"
            );
            internal_error_response(error)
        }
    }
}

/// `GET /chipbot/tracks/{isrc}/file/only-cache` — format omitted, defaults to mp3.
pub async fn get_track_file_only_cache_by_isrc_default(
    State(state): State<AppState>,
    Path(raw_isrc): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match get_track_file_only_cache_by_isrc_inner(&state, raw_isrc, "mp3".to_string(), &headers, bw)
        .await
    {
        Ok(response) => response,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileOnlyCacheByIsrcDefault"
            );
            internal_error_response(error)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn validation_normalizes_isrc_and_accepts_all_ts_formats() {
        for format in ["mp3", ".webm", "flac", ".ogg", "m4a", ".wav"] {
            let validation = validate_file_request(" usrc17607839 ", format);
            assert!(!validation.errors.has_errors, "{format}");
            assert_eq!(validation.isrc.as_deref(), Some("USRC17607839"));
            assert!(is_audio_extension(&validation.requested_format));
        }
    }

    #[test]
    fn validation_accumulates_isrc_and_format_errors() {
        let validation = validate_file_request("not-an-isrc", "AAC");
        assert!(validation.errors.has_errors);
        assert_eq!(validation.errors.status_code, 400);
        assert_eq!(validation.errors.errors.len(), 2);
        assert_eq!(
            validation.errors.errors[0].message,
            "Valid ISRC is required"
        );
        assert_eq!(validation.errors.errors[1].message, "Invalid track format");
        assert!(
            validate_file_request("USRC17607839", "MP3")
                .errors
                .has_errors
        );
    }

    #[test]
    fn filename_and_manifest_mapping_are_safe_and_normalized() {
        assert_eq!(
            cache_filename(" usrc17607839 ", ".m4a").as_deref(),
            Some("USRC17607839.m4a")
        );
        assert_eq!(
            manifest_filename("usrc17607839", ".mp3").as_deref(),
            Some("tmp-chipbot/USRC17607839.mp3")
        );
        assert_eq!(cache_filename("../escape", ".mp3"), None);
        assert_eq!(cache_filename("USRC17607839", ".aac"), None);
    }

    #[test]
    fn audio_url_extension_mapping_matches_ts_fallback() {
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.flac?x=1").unwrap()),
            Some(".flac")
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song").unwrap()),
            Some(".mp3")
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.aac").unwrap()),
            None
        );
        assert_eq!(
            audio_extension_from_url(&Url::parse("https://cdn.test/song.MP3").unwrap()),
            None
        );
        assert!(allowed_audio_url("ftp://cdn.test/song.mp3").is_none());
        assert!(allowed_audio_url("https://cdn.test/song.mp3").is_some());
    }
}

