1	//! Chipbot provider.
2	//!
3	//! Source: `services/api-music-nodo/src/infrastructure/services/chipbot-service.ts`.
4	//!
5	//! The chipbot upstream speaks one HTTP endpoint — `GET {url}/tracks?isrc=...`
6	//! with a Bearer token — and is consumed by:
7	//!
8	//! - [`ChipbotService::health`] — liveness probe driven by the
9	//!   `HealthCheckWorker`. Hits the same endpoint with a sentinel ISRC that
10	//!   can never match a real release (`CHIPBOT_HEALTH_SENTINEL_ISRC`); a
11	//!   `200` (with empty results) or `404` both prove the API and the token
12	//!   are reachable, every other status (or any network/abort failure) is
13	//!   reported as a non-healthy result.
14	//! - [`ChipbotService::get_track_by_isrc`] — metadata lookup. The audio
15	//!   stream itself is fetched by the chipbot controller in a separate
16	//!   `GET <audio.url>` call (see `CHIPBOT_FETCH_TIMEOUT_MS = 15_000` in
17	//!   `chipbot-controller.ts`); the provider only exposes `ChipbotTrack` so
18	//!   the controller can pull `track.audio.url` and stream it to disk.
19	//!
20	//! Both call sites receive a `bw: Option<&BandwidthOp>` so a probe started
21	//! outside an HTTP request (the health-check worker) can run without an
22	//! active bandwidth context, exactly mirroring the TS
23	//! `getActiveBandwidthContext()` shape.
24	
25	use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
26	
27	use serde::{Deserialize, Serialize};
28	use thiserror::Error;
29	use tracing::{debug, error, warn};
30	
31	use crate::cache::health::HealthCheckResult;
32	use crate::telemetry::{BandwidthOp, BandwidthProvider};
33	
34	// ---------------------------------------------------------------------------
35	// Constants — values frozen against `chipbot-service.ts`.
36	// ---------------------------------------------------------------------------
37	
38	/// `CHIPBOT_HEALTH_TIMEOUT_MS = 5_000` in chipbot-service.ts:8.
39	const CHIPBOT_HEALTH_TIMEOUT_MS: u64 = 5_000;
40	
41	/// `CHIPBOT_HEALTH_SENTINEL_ISRC = "ZZZZ99999999"` in chipbot-service.ts:13.
42	///
43	/// Well-formed ISRC pattern (`[A-Z]{2}[A-Z0-9]{3}\d{7}` — the controller's
44	/// `normalizeIsrc` validates this exact shape before lookup). It cannot
45	/// match a real release, so an upstream 200 with empty results or a 404 is
46	/// the expected, healthy response.
47	const CHIPBOT_HEALTH_SENTINEL_ISRC: &str = "ZZZZ99999999";
48	
49	/// Data-path (`/tracks?isrc=...`) timeout, mirroring the
50	/// `new UndiciClient({ timeout: 10_000 })` in chipbot-service.ts:44. The
51	/// controller's audio-download path uses a separate 15 s budget
52	/// (`CHIPBOT_FETCH_TIMEOUT_MS` in chipbot-controller.ts:18); we don't carry
53	/// that surface here because the audio fetch lives in the controller.
54	const CHIPBOT_DATA_TIMEOUT_MS: u64 = 10_000;
55	
56	/// Strip trailing slashes before appending the `/tracks` path. Mirrors the
57	/// same `replace(/\/+$/, "")` used by `health()` in chipbot-service.ts:77.
58	fn base_url_stripped(url: &str) -> String {
59	    let trimmed = url.trim();
60	    let trimmed = trimmed.trim_end_matches('/');
61	    trimmed.to_string()
62	}
63	
64	// ---------------------------------------------------------------------------
65	// DTOs — wire-compatible with the upstream JSON.
66	//
67	// `isrc`/`title`/etc. are required strings in TS, but the upstream JSON
68	// has been observed to occasionally drop fields (e.g. `artist` empty for
69	// spoken-word releases). We round-trip through `serde_json::Value` for the
70	// audio metadata block to keep the struct tolerant of upstream drift
71	// without changing the public Rust surface.
72	// ---------------------------------------------------------------------------
73	
74	/// Upstream track object. Matches `ChipbotTrack` in chipbot-service.ts:15-27.
75	///
76	/// `audio` is nullable because the upstream returns `{... audio: null}` when
77	/// it has catalogued the metadata but cannot serve a stream. The chipbot
78	/// controller treats any `status:"ok"` track without a usable `audio.url`
79	/// as a cache miss (chipbot-controller.ts:206-218), so we surface this
80	/// exactly.
81	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
82	pub struct ChipbotTrack {
83	    pub isrc: String,
84	    pub title: String,
85	    pub artist: String,
86	    pub artwork: Option<String>,
87	    pub duration_ms: u64,
88	    #[serde(default)]
89	    pub genres: Vec<String>,
90	    #[serde(default)]
91	    pub audio: Option<ChipbotAudio>,
92	}
93	
94	/// `track.audio` block in chipbot-service.ts:21-26.
95	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
96	pub struct ChipbotAudio {
97	    pub quality: u32,
98	    pub url: String,
99	    pub downloaded_at: String,
100	}
101	
102	#[derive(Debug, Deserialize)]
103	struct ChipbotTracksResponse {
104	    #[allow(dead_code)] // The TS reads this for shape parity, we ignore it.
105	    count: u64,
106	    results: Vec<ChipbotTrack>,
107	}
108	
109	// ---------------------------------------------------------------------------
110	// Provider error — module-local `thiserror` enum for internal helpers.
111	//
112	// Matches RadioPort's guidance: the public surface (`get_track_by_isrc`)
113	// flattens every error case to `Option<ChipbotTrack>` because the TS
114	/// controller treats `not_found` and `error` identically (a 404 from the
115	/// upstream matches an HTTP-level error in this layer's contract). The
116	/// enum exists so URL/request construction stays in named failure paths
117	/// and so the helpers can `?` instead of nesting matches.
118	// ---------------------------------------------------------------------------
119	
120	#[derive(Debug, Error)]
121	pub enum ChipbotError {
122	    #[error("invalid chipbot base URL: {0}")]
123	    InvalidBaseUrl(String),
124	
125	    #[error("chipbot upstream request failed: {0}")]
126	    Upstream(String),
127	}
128	
129	// ---------------------------------------------------------------------------
130	// Service
131	// ---------------------------------------------------------------------------
132	
133	#[derive(Clone)]
134	pub struct ChipbotService {
135	    http: reqwest::Client,
136	    base_url: String,
137	    bearer: String,
138	}
139	
140	impl ChipbotService {
141	    /// Construct from a shared `reqwest::Client` and the typed `ServiceConfig`
142	    /// group for chipbot (`{url, token}`).
143	    pub fn new(http: reqwest::Client, config: crate::config::ServiceConfig) -> Self {
144	        Self {
145	            http,
146	            base_url: base_url_stripped(&config.url),
147	            bearer: config.token,
148	        }
149	    }
150	
151	    /// Liveness probe used by the `HealthCheckWorker` and exposed via
152	    /// `GET /chipbot/health`.
153	    ///
154	    /// Mirrors `ChipbotService.health` in chipbot-service.ts:64-113:
155	    /// - missing config → `{ ok: false, responseMs: 0, checkedAt, error }`;
156	    /// - 200 (empty results) or 404 → `{ ok: true, responseMs, checkedAt }`;
157	    /// - any other status → `{ ok: false, responseMs, checkedAt, error: { message, code } }`;
158	    /// - network/abort failure → `{ ok: false, responseMs, checkedAt, error: { message } }`.
159	    ///
160	    /// `bw` is optional: when the worker polls outside an HTTP request there
161	    /// is no active bandwidth context (the TS side passes nothing too).
162	    pub async fn health(&self, bw: Option<&BandwidthOp>) -> HealthCheckResult {
163	        let checked_at = now_ms();
164	        if self.base_url.is_empty() || self.bearer.is_empty() {
165	            return HealthCheckResult {
166	                ok: false,
167	                response_ms: 0,
168	                checked_at,
169	                error: Some(crate::cache::health::HealthCheckError {
170	                    message: "Chipbot config missing (url or token)".to_string(),
171	                    code: None,
172	                }),
173	            };
174	        }
175	
176	        if let Some(op) = bw {
177	            op.set_provider(BandwidthProvider::Chipbot);
178	            op.set_route("/chipbot/health");
179	        }
180	
181	        let url = format!(
182	            "{}/tracks?isrc={}",
183	            self.base_url, CHIPBOT_HEALTH_SENTINEL_ISRC
184	        );
185	        let start = Instant::now();
186	        let request = self
187	            .http
188	            .get(&url)
189	            .bearer_auth(&self.bearer)
190	            .header("Accept", "application/json")
191	            .timeout(Duration::from_millis(CHIPBOT_HEALTH_TIMEOUT_MS));
192	        let result = request.send().await;
193	        let response_ms = start.elapsed().as_millis() as u64;
194	
195	        match result {
196	            Ok(response) => {
197	                let status = response.status();
198	                if status == reqwest::StatusCode::OK || status == reqwest::StatusCode::NOT_FOUND {
199	                    return HealthCheckResult {
200	                        ok: true,
201	                        response_ms,
202	                        checked_at,
203	                        error: None,
204	                    };
205	                }
206	                warn!(
207	                    target: "chipbot",
208	                    url = %url,
209	                    status = status.as_u16(),
210	                    "ChipbotService - health: unexpected status"
211	                );
212	                if let Some(op) = bw {
213	                    op.add_upstream_requests(1);
214	                }
215	                HealthCheckResult {
216	                    ok: false,
217	                    response_ms,
218	                    checked_at,
219	                    error: Some(crate::cache::health::HealthCheckError {
220	                        message: format!("HTTP {}", status.as_u16()),
221	                        code: Some(status.as_u16().to_string()),
222	                    }),
223	                }
224	            }
225	            Err(error) => {
226	                warn!(
227	                    target: "chipbot",
228	                    url = %url,
229	                    error = %error,
230	                    "ChipbotService - health: fetch failed"
231	                );
232	                if let Some(op) = bw {
233	                    op.add_upstream_requests(1);
234	                }
235	                HealthCheckResult {
236	                    ok: false,
237	                    response_ms,
238	                    checked_at,
239	                    error: Some(crate::cache::health::HealthCheckError {
240	                        message: format_upstream_error(&error),
241	                        code: None,
242	                    }),
243	                }
244	            }
245	        }
246	    }
247	
248	    /// Look up a track by ISRC.
249	    ///
250	    /// Mirrors `ChipbotService.getTrackByIsrc` in chipbot-service.ts:115-142:
251	    /// - missing config → `warn!` + `None`;
252	    /// - upstream 2xx with `results[0]` → `Some(track)`;
253	    /// - upstream 2xx with empty results → `None`;
254	    /// - upstream 4xx/5xx, non-JSON body, or network error → `error!` + `None`.
255	    ///
256	    /// The TS returns a `{ status: ok|not_found|error }` discriminated union,
257	    /// but the controller collapses both `not_found` and `error` into the
258	    /// same 404 response (chipbot-controller.ts:206-218 / 220-225). We
259	    /// flatten at the provider boundary for the same reason RadioPort
260	    /// flattened `RadioService::get_channel` to `Option<RadioStation>`.
261	    pub async fn get_track_by_isrc(
262	        &self,
263	        isrc: &str,
264	        bw: Option<&BandwidthOp>,
265	    ) -> Option<ChipbotTrack> {
266	        if let Some(op) = bw {
267	            op.set_provider(BandwidthProvider::Chipbot);
268	        }
269	
270	        if self.base_url.is_empty() || self.bearer.is_empty() {
271	            warn!(target: "chipbot", "ChipbotService - missing configuration");
272	            return None;
273	        }
274	
275	        let url = match self.build_tracks_url(isrc) {
276	            Ok(url) => url,
277	            Err(error) => {
278	                error!(
279	                    target: "chipbot",
280	                    isrc,
281	                    error = %error,
282	                    "ChipbotService - getTrackByIsrc: invalid URL"
283	                );
284	                return None;
285	            }
286	        };
287	
288	        debug!(target: "chipbot", isrc, url = %url, "ChipbotService - getTrackByIsrc");
289	
290	        let request = self
291	            .http
292	            .get(&url)
293	            .bearer_auth(&self.bearer)
294	            .header("Accept", "*/*")
295	            .timeout(Duration::from_millis(CHIPBOT_DATA_TIMEOUT_MS));
296	        let send_result = request.send().await;
297	        let response = match send_result {
298	            Ok(r) => r,
299	            Err(error) => {
300	                error!(
301	                    target: "chipbot",
302	                    isrc,
303	                    error = %error,
304	                    "ChipbotService - getTrackByIsrc"
305	                );
306	                return None;
307	            }
308	        };
309	
310	        let status = response.status();
311	        if let Some(op) = bw {
312	            op.add_upstream_requests(1);
313	        }
314	
315	        if !status.is_success() {
316	            error!(
317	                target: "chipbot",
318	                isrc,
319	                status = status.as_u16(),
320	                "ChipbotService - getTrackByIsrc: non-success status"
321	            );
322	            return None;
323	        }
324	
325	        let body = match response.bytes().await {
326	            Ok(b) => b,
327	            Err(error) => {
328	                error!(
329	                    target: "chipbot",
330	                    isrc,
331	                    error = %error,
332	                    "ChipbotService - getTrackByIsrc: body read failed"
333	                );
334	                return None;
335	            }
336	        };
337	
338	        if let Some(op) = bw {
339	            op.add_upstream_received(body.len() as u64);
340	        }
341	
342	        let parsed: ChipbotTracksResponse = match serde_json::from_slice(&body) {
343	            Ok(v) => v,
344	            Err(error) => {
345	                error!(
346	                    target: "chipbot",
347	                    isrc,
348	                    error = %error,
349	                    "ChipbotService - getTrackByIsrc: invalid JSON"
350	                );
351	                return None;
352	            }
353	        };
354	
355	        parsed.results.into_iter().next()
356	    }
357	
358	    fn build_tracks_url(&self, isrc: &str) -> Result<String, ChipbotError> {
359	        if self.base_url.is_empty() {
360	            return Err(ChipbotError::InvalidBaseUrl(self.base_url.clone()));
361	        }
362	        let endpoint = format!("{}/tracks?isrc={}", self.base_url, urlencode_isrc(isrc));
363	        Ok(endpoint)
364	    }
365	}
366	
367	// ---------------------------------------------------------------------------
368	// Helpers
369	// ---------------------------------------------------------------------------
370	
371	/// `encodeURIComponent(isrc)` in chipbot-service.ts:125. ISRCs are
372	/// case-normalized alphanumeric so the value is identifier-safe in
373	/// practice, but a defensive encode keeps us aligned with the TS request
374	/// URL even if a caller passes whitespace or punctuation.
375	fn urlencode_isrc(isrc: &str) -> String {
376	    // Hand-rolled percent-encoding for the ISRC character class. `url`
377	    // crate's `form_urlencoded` would emit `+` for spaces; the TS
378	    // `encodeURIComponent` emits `%20`, and we want byte parity with the
379	    // upstream so Redis keys and request log lines match exactly.
380	    let mut out = String::with_capacity(isrc.len());
381	    for byte in isrc.bytes() {
382	        match byte {
383	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
384	                out.push(byte as char);
385	            }
386	            _ => out.push_str(&format!("%{:02X}", byte)),
387	        }
388	    }
389	    out
390	}
391	
392	fn now_ms() -> u64 {
393	    SystemTime::now()
394	        .duration_since(UNIX_EPOCH)
395	        .map(|d| d.as_millis() as u64)
396	        .unwrap_or(0)
397	}
398	
399	fn format_upstream_error(error: &reqwest::Error) -> String {
400	    if error.is_timeout() {
401	        "request timed out".to_string()
402	    } else if error.is_connect() {
403	        format!("connect error: {}", error)
404	    } else if error.is_decode() {
405	        format!("decode error: {}", error)
406	    } else {
407	        error.to_string()
408	    }
409	}
410	
411	// ---------------------------------------------------------------------------
412	// Tests — colocated, wiremock-backed. Each test gets its own mock server
413	// and a fresh service so there is no shared state.
414	// ---------------------------------------------------------------------------
415	
416	#[cfg(test)]
417	mod tests {
418	    use super::*;
