427	        }
428	    }
429	
430	    fn service_for(server: &MockServer) -> ChipbotService {
431	        ChipbotService::new(reqwest::Client::new(), config(&server.uri(), "test-bearer"))
432	    }
433	
434	    #[tokio::test]
435	    async fn get_track_by_isrc_returns_first_result_on_200() {
436	        let server = MockServer::start().await;
437	        let body = serde_json::json!({
