//! Chipbot provider.
//!
//! Source: `services/api-music-nodo/src/infrastructure/services/chipbot-service.ts`.
//!
//! The chipbot upstream speaks one HTTP endpoint — `GET {url}/tracks?isrc=...`
//! with a Bearer token — and is consumed by:
//!
//! - [`ChipbotService::health`] — liveness probe driven by the
//!   `HealthCheckWorker`. Hits the same endpoint with a sentinel ISRC that
//!   can never match a real release (`CHIPBOT_HEALTH_SENTINEL_ISRC`); a
//!   `200` (with empty results) or `404` both prove the API and the token
//!   are reachable, every other status (or any network/abort failure) is
//!   reported as a non-healthy result.
//! - [`ChipbotService::get_track_by_isrc`] — metadata lookup. The audio
//!   stream itself is fetched by the chipbot controller in a separate
//!   `GET <audio.url>` call (see `CHIPBOT_FETCH_TIMEOUT_MS = 15_000` in
//!   `chipbot-controller.ts`); the provider only exposes `ChipbotTrack` so
//!   the controller can pull `track.audio.url` and stream it to disk.
//!
//! Both call sites receive a `bw: Option<&BandwidthOp>` so a probe started
//! outside an HTTP request (the health-check worker) can run without an
//! active bandwidth context, exactly mirroring the TS
//! `getActiveBandwidthContext()` shape.

use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};
use thiserror::Error;
use tracing::{debug, error, warn};

use crate::cache::health::HealthCheckResult;
use crate::telemetry::{BandwidthOp, BandwidthProvider};

// ---------------------------------------------------------------------------
// Constants — values frozen against `chipbot-service.ts`.
// ---------------------------------------------------------------------------

/// `CHIPBOT_HEALTH_TIMEOUT_MS = 5_000` in chipbot-service.ts:8.
const CHIPBOT_HEALTH_TIMEOUT_MS: u64 = 5_000;

/// `CHIPBOT_HEALTH_SENTINEL_ISRC = "ZZZZ99999999"` in chipbot-service.ts:13.
///
/// Well-formed ISRC pattern (`[A-Z]{2}[A-Z0-9]{3}\d{7}` — the controller's
/// `normalizeIsrc` validates this exact shape before lookup). It cannot
/// match a real release, so an upstream 200 with empty results or a 404 is
/// the expected, healthy response.
const CHIPBOT_HEALTH_SENTINEL_ISRC: &str = "ZZZZ99999999";

/// Data-path (`/tracks?isrc=...`) timeout, mirroring the
/// `new UndiciClient({ timeout: 10_000 })` in chipbot-service.ts:44. The
/// controller's audio-download path uses a separate 15 s budget
/// (`CHIPBOT_FETCH_TIMEOUT_MS` in chipbot-controller.ts:18); we don't carry
/// that surface here because the audio fetch lives in the controller.
const CHIPBOT_DATA_TIMEOUT_MS: u64 = 10_000;

/// Strip trailing slashes before appending the `/tracks` path. Mirrors the
/// same `replace(/\/+$/, "")` used by `health()` in chipbot-service.ts:77.
fn base_url_stripped(url: &str) -> String {
    let trimmed = url.trim();
    let trimmed = trimmed.trim_end_matches('/');
    trimmed.to_string()
}

// ---------------------------------------------------------------------------
// DTOs — wire-compatible with the upstream JSON.
//
// `isrc`/`title`/etc. are required strings in TS, but the upstream JSON
// has been observed to occasionally drop fields (e.g. `artist` empty for
// spoken-word releases). We round-trip through `serde_json::Value` for the
// audio metadata block to keep the struct tolerant of upstream drift
// without changing the public Rust surface.
// ---------------------------------------------------------------------------

/// Upstream track object. Matches `ChipbotTrack` in chipbot-service.ts:15-27.
///
/// `audio` is nullable because the upstream returns `{... audio: null}` when
/// it has catalogued the metadata but cannot serve a stream. The chipbot
/// controller treats any `status:"ok"` track without a usable `audio.url`
/// as a cache miss (chipbot-controller.ts:206-218), so we surface this
/// exactly.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ChipbotTrack {
    pub isrc: String,
    pub title: String,
    pub artist: String,
    pub artwork: Option<String>,
    pub duration_ms: u64,
    #[serde(default)]
    pub genres: Vec<String>,
    #[serde(default)]
    pub audio: Option<ChipbotAudio>,
}

/// `track.audio` block in chipbot-service.ts:21-26.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ChipbotAudio {
    pub quality: u32,
    pub url: String,
    pub downloaded_at: String,
}

#[derive(Debug, Deserialize)]
struct ChipbotTracksResponse {
    #[allow(dead_code)] // The TS reads this for shape parity, we ignore it.
    count: u64,
    results: Vec<ChipbotTrack>,
}

// ---------------------------------------------------------------------------
// Provider error — module-local `thiserror` enum for internal helpers.
//
// Matches RadioPort's guidance: the public surface (`get_track_by_isrc`)
// flattens every error case to `Option<ChipbotTrack>` because the TS
/// controller treats `not_found` and `error` identically (a 404 from the
/// upstream matches an HTTP-level error in this layer's contract). The
/// enum exists so URL/request construction stays in named failure paths
/// and so the helpers can `?` instead of nesting matches.
// ---------------------------------------------------------------------------

#[derive(Debug, Error)]
pub enum ChipbotError {
    #[error("invalid chipbot base URL: {0}")]
    InvalidBaseUrl(String),

    #[error("chipbot upstream request failed: {0}")]
    Upstream(String),
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct ChipbotService {
    http: reqwest::Client,
    base_url: String,
    bearer: String,
}

impl ChipbotService {
    /// Construct from a shared `reqwest::Client` and the typed `ServiceConfig`
    /// group for chipbot (`{url, token}`).
    pub fn new(http: reqwest::Client, config: crate::config::ServiceConfig) -> Self {
        Self {
            http,
            base_url: base_url_stripped(&config.url),
            bearer: config.token,
        }
    }

    /// Liveness probe used by the `HealthCheckWorker` and exposed via
    /// `GET /chipbot/health`.
    ///
    /// Mirrors `ChipbotService.health` in chipbot-service.ts:64-113:
    /// - missing config → `{ ok: false, responseMs: 0, checkedAt, error }`;
    /// - 200 (empty results) or 404 → `{ ok: true, responseMs, checkedAt }`;
    /// - any other status → `{ ok: false, responseMs, checkedAt, error: { message, code } }`;
    /// - network/abort failure → `{ ok: false, responseMs, checkedAt, error: { message } }`.
    ///
    /// `bw` is optional: when the worker polls outside an HTTP request there
    /// is no active bandwidth context (the TS side passes nothing too).
    pub async fn health(&self, bw: Option<&BandwidthOp>) -> HealthCheckResult {
        let checked_at = now_ms();
        if self.base_url.is_empty() || self.bearer.is_empty() {
            return HealthCheckResult {
                ok: false,
                response_ms: 0,
                checked_at,
                error: Some(crate::cache::health::HealthCheckError {
                    message: "Chipbot config missing (url or token)".to_string(),
                    code: None,
                }),
            };
        }

        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Chipbot);
            op.set_route("/chipbot/health");
        }

        let url = format!(
            "{}/tracks?isrc={}",
            self.base_url, CHIPBOT_HEALTH_SENTINEL_ISRC
        );
        let start = Instant::now();
        let request = self
            .http
            .get(&url)
            .bearer_auth(&self.bearer)
            .header("Accept", "application/json")
            .timeout(Duration::from_millis(CHIPBOT_HEALTH_TIMEOUT_MS));
        let result = request.send().await;
        let response_ms = start.elapsed().as_millis() as u64;

        match result {
            Ok(response) => {
                let status = response.status();
                if status == reqwest::StatusCode::OK || status == reqwest::StatusCode::NOT_FOUND {
                    return HealthCheckResult {
                        ok: true,
                        response_ms,
                        checked_at,
                        error: None,
                    };
                }
                warn!(
                    target: "chipbot",
                    url = %url,
                    status = status.as_u16(),
                    "ChipbotService - health: unexpected status"
                );
                if let Some(op) = bw {
                    op.add_upstream_requests(1);
                }
                HealthCheckResult {
                    ok: false,
                    response_ms,
                    checked_at,
                    error: Some(crate::cache::health::HealthCheckError {
                        message: format!("HTTP {}", status.as_u16()),
                        code: Some(status.as_u16().to_string()),
                    }),
                }
            }
            Err(error) => {
                warn!(
                    target: "chipbot",
                    url = %url,
                    error = %error,
                    "ChipbotService - health: fetch failed"
                );
                if let Some(op) = bw {
                    op.add_upstream_requests(1);
                }
                HealthCheckResult {
                    ok: false,
                    response_ms,
                    checked_at,
                    error: Some(crate::cache::health::HealthCheckError {
                        message: format_upstream_error(&error),
                        code: None,
                    }),
                }
            }
        }
    }

    /// Look up a track by ISRC.
    ///
    /// Mirrors `ChipbotService.getTrackByIsrc` in chipbot-service.ts:115-142:
    /// - missing config → `warn!` + `None`;
    /// - upstream 2xx with `results[0]` → `Some(track)`;
    /// - upstream 2xx with empty results → `None`;
    /// - upstream 4xx/5xx, non-JSON body, or network error → `error!` + `None`.
    ///
    /// The TS returns a `{ status: ok|not_found|error }` discriminated union,
    /// but the controller collapses both `not_found` and `error` into the
    /// same 404 response (chipbot-controller.ts:206-218 / 220-225). We
    /// flatten at the provider boundary for the same reason RadioPort
    /// flattened `RadioService::get_channel` to `Option<RadioStation>`.
    pub async fn get_track_by_isrc(
        &self,
        isrc: &str,
        bw: Option<&BandwidthOp>,
    ) -> Option<ChipbotTrack> {
        if let Some(op) = bw {
            op.set_provider(BandwidthProvider::Chipbot);
        }

        if self.base_url.is_empty() || self.bearer.is_empty() {
            warn!(target: "chipbot", "ChipbotService - missing configuration");
            return None;
        }

        let url = match self.build_tracks_url(isrc) {
            Ok(url) => url,
            Err(error) => {
                error!(
                    target: "chipbot",
                    isrc,
                    error = %error,
                    "ChipbotService - getTrackByIsrc: invalid URL"
                );
                return None;
            }
        };

        debug!(target: "chipbot", isrc, url = %url, "ChipbotService - getTrackByIsrc");

        let request = self
            .http
            .get(&url)
            .bearer_auth(&self.bearer)
            .header("Accept", "*/*")
            .timeout(Duration::from_millis(CHIPBOT_DATA_TIMEOUT_MS));
        let send_result = request.send().await;
        let response = match send_result {
            Ok(r) => r,
            Err(error) => {
                error!(
                    target: "chipbot",
                    isrc,
                    error = %error,
                    "ChipbotService - getTrackByIsrc"
                );
                return None;
            }
        };

        let status = response.status();
        if let Some(op) = bw {
            op.add_upstream_requests(1);
        }

        if !status.is_success() {
            error!(
                target: "chipbot",
                isrc,
                status = status.as_u16(),
                "ChipbotService - getTrackByIsrc: non-success status"
            );
            return None;
        }

        let body = match response.bytes().await {
            Ok(b) => b,
            Err(error) => {
                error!(
                    target: "chipbot",
                    isrc,
                    error = %error,
                    "ChipbotService - getTrackByIsrc: body read failed"
                );
                return None;
            }
        };

        if let Some(op) = bw {
            op.add_upstream_received(body.len() as u64);
        }

        let parsed: ChipbotTracksResponse = match serde_json::from_slice(&body) {
            Ok(v) => v,
            Err(error) => {
                error!(
                    target: "chipbot",
                    isrc,
                    error = %error,
                    "ChipbotService - getTrackByIsrc: invalid JSON"
                );
                return None;
            }
        };

        parsed.results.into_iter().next()
    }

    fn build_tracks_url(&self, isrc: &str) -> Result<String, ChipbotError> {
        if self.base_url.is_empty() {
            return Err(ChipbotError::InvalidBaseUrl(self.base_url.clone()));
        }
        let endpoint = format!("{}/tracks?isrc={}", self.base_url, urlencode_isrc(isrc));
        Ok(endpoint)
    }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// `encodeURIComponent(isrc)` in chipbot-service.ts:125. ISRCs are
/// case-normalized alphanumeric so the value is identifier-safe in
/// practice, but a defensive encode keeps us aligned with the TS request
/// URL even if a caller passes whitespace or punctuation.
fn urlencode_isrc(isrc: &str) -> String {
    // Hand-rolled percent-encoding for the ISRC character class. `url`
    // crate's `form_urlencoded` would emit `+` for spaces; the TS
    // `encodeURIComponent` emits `%20`, and we want byte parity with the
    // upstream so Redis keys and request log lines match exactly.
    let mut out = String::with_capacity(isrc.len());
    for byte in isrc.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(byte as char);
            }
            _ => out.push_str(&format!("%{:02X}", byte)),
        }
    }
    out
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

fn format_upstream_error(error: &reqwest::Error) -> String {
    if error.is_timeout() {
        "request timed out".to_string()
    } else if error.is_connect() {
        format!("connect error: {}", error)
    } else if error.is_decode() {
        format!("decode error: {}", error)
    } else {
        error.to_string()
    }
}

// ---------------------------------------------------------------------------
// Tests — colocated, wiremock-backed. Each test gets its own mock server
// and a fresh service so there is no shared state.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    use wiremock::matchers::{method, path, query_param};
    use wiremock::{Mock, MockServer, ResponseTemplate};

    fn config(url: &str, token: &str) -> crate::config::ServiceConfig {
        crate::config::ServiceConfig {
            url: url.to_string(),
            token: token.to_string(),
        }
    }

    fn service_for(server: &MockServer) -> ChipbotService {
        ChipbotService::new(reqwest::Client::new(), config(&server.uri(), "test-bearer"))
    }

    #[tokio::test]
    async fn get_track_by_isrc_returns_first_result_on_200() {
        let server = MockServer::start().await;
        let body = serde_json::json!({
            "count": 1,
            "results": [
                {
                    "isrc": "USRC17607839",
                    "title": "Test Track",
                    "artist": "Tester",
                    "artwork": "https://example.test/art.jpg",
                    "duration_ms": 180000,
                    "genres": ["pop"],
                    "audio": {
                        "quality": 1,
                        "url": "https://example.test/audio.mp3",
                        "downloaded_at": "2025-01-01T00:00:00.000Z"
                    }
                }
            ]
        });
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", "USRC17607839"))
            .respond_with(ResponseTemplate::new(200).set_body_json(body))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let track = service
            .get_track_by_isrc("USRC17607839", None)
            .await
            .expect("track present");
        assert_eq!(track.isrc, "USRC17607839");
        assert_eq!(track.title, "Test Track");
        let audio = track.audio.expect("audio block present");
        assert_eq!(audio.url, "https://example.test/audio.mp3");
        assert_eq!(audio.quality, 1);
        assert_eq!(audio.downloaded_at, "2025-01-01T00:00:00.000Z");
    }

    #[tokio::test]
    async fn get_track_by_isrc_returns_none_on_404() {
        let server = MockServer::start().await;
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", "USRC17607839"))
            .respond_with(ResponseTemplate::new(404))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let track = service.get_track_by_isrc("USRC17607839", None).await;
        assert!(track.is_none());
    }

    #[tokio::test]
    async fn get_track_by_isrc_returns_none_on_empty_results() {
        let server = MockServer::start().await;
        let body = serde_json::json!({ "count": 0, "results": [] });
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", "USRC17607839"))
            .respond_with(ResponseTemplate::new(200).set_body_json(body))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let track = service.get_track_by_isrc("USRC17607839", None).await;
        assert!(track.is_none());
    }

    #[tokio::test]
    async fn get_track_by_isrc_returns_none_without_http_when_config_missing() {
        // No mock mounted; if the provider hits upstream the test fails via
        // an unmet expectation (or, when no mock is registered, by hanging).
        let server = MockServer::start().await;
        // Build a "missing" config by starting from a token-only string and
        // an empty URL — the TS service checks both individually.
        let service = ChipbotService::new(reqwest::Client::new(), config("", ""));
        let track = service.get_track_by_isrc("USRC17607839", None).await;
        assert!(track.is_none());
        // server is unused; drop the binding so we don't keep the handle.
        drop(server);
    }

    #[tokio::test]
    async fn health_ok_on_404_sentinel_response() {
        let server = MockServer::start().await;
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", CHIPBOT_HEALTH_SENTINEL_ISRC))
            .respond_with(ResponseTemplate::new(404))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let result = service.health(None).await;
        assert!(result.ok, "404 sentinel should be healthy, got: {result:?}");
        assert_eq!(result.error, None);
        assert!(result.response_ms < 10_000);
        assert!(result.checked_at > 0);
    }

    #[tokio::test]
    async fn health_ok_on_200_with_empty_results() {
        let server = MockServer::start().await;
        let body = serde_json::json!({ "count": 0, "results": [] });
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", CHIPBOT_HEALTH_SENTINEL_ISRC))
            .respond_with(ResponseTemplate::new(200).set_body_json(body))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let result = service.health(None).await;
        assert!(result.ok, "200 with empty results should be healthy");
    }

    #[tokio::test]
    async fn health_fail_on_500() {
        let server = MockServer::start().await;
        Mock::given(method("GET"))
            .and(path("/tracks"))
            .and(query_param("isrc", CHIPBOT_HEALTH_SENTINEL_ISRC))
            .respond_with(ResponseTemplate::new(500))
            .expect(1)
            .mount(&server)
            .await;

        let service = service_for(&server);
        let result = service.health(None).await;
        assert!(!result.ok);
        let error = result.error.expect("error envelope on non-healthy");
        assert!(error.message.contains("500"), "got: {:?}", error.message);
        assert_eq!(error.code.as_deref(), Some("500"));
    }

    #[tokio::test]
    async fn health_fail_without_http_when_config_missing() {
        let service = ChipbotService::new(reqwest::Client::new(), config("", ""));
        let result = service.health(None).await;
        assert!(!result.ok);
        assert_eq!(result.response_ms, 0);
        let error = result.error.expect("error envelope on missing config");
        assert!(
            error.message.contains("missing"),
            "got: {:?}",
            error.message
        );
    }
}

