1	//! Port of `deezer-controller.ts` (prefix `/deezer`, 8 routes).
2	//!
3	//! Adaptador fino tras la Fase 2 del refactor: la orquestación de archivos
4	//! (locks, pipeline de descarga, mp3val, manifiestos, contador) vive en
5	//! `crate::system::deezer_files`; aquí solo queda la traducción HTTP —
6	//! parseo de rutas/query, envelopes a `Response` y el streaming con soporte
7	//! `Range` (RFC 7233) sobre el `AudioServe::File` que devuelve el núcleo.
8	//!
9	//! Observable contract (mirrored exactly):
10	//! - `/health` -> 200 `"OK"` / 500 `"UNAVAILABLE"` (no envelope error).
11	//! - `/tracks/{id}` + `/tracks/by-isrc/{isrc}` -> provider envelope
12	//!   pass-through, 404 fallback handled inside the provider (`DeezerResult`
13	//!   errors carry their own status).
14	//! - `/tracks/{id}/tokens` -> session tokens + cached track token, 401 on
15	//!   license errors, 500 on transport failures.
16	//! - `/tracks/{id}/file/{format}`, `/file`, `/file/only-cache` y
17	//!   `/file/{format}/only-cache` -> ver `system::deezer_files` (casos 5-8
18	//!   del catálogo docs/CASOS_DE_USO.md).
19	//! - `/autocomplete` + `/search` -> query normalizada (NFKC + invisibles),
20	//!   `limit` 1..=25 (default 10); fallos upstream se aplanan a payload vacío.
21	
22	use std::path::Path as FsPath;
23	
24	use axum::extract::{Extension, Path, RawQuery, State};
25	use axum::http::{header, HeaderMap, StatusCode};
26	use axum::response::{IntoResponse, Response};
27	use axum::Json;
28	use serde::Serialize;
29	use serde_json::Value;
30	
31	use crate::audio::{file_response, parse_range};
32	use crate::cache::keys::normalize_query_text;
33	use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
34	use crate::providers::deezer::DeezerTrackInfo;
35	use crate::state::AppState;
36	use crate::system::{AudioServe, Tipo};
37	use crate::telemetry::BandwidthOp;
38	
39	const SEARCH_LIMIT_MIN: i64 = 1;
40	const SEARCH_LIMIT_MAX: i64 = 25;
41	const SEARCH_LIMIT_DEFAULT: i64 = 10;
42	
43	// ---------------------------------------------------------------------------
44	// Shared helpers
45	// ---------------------------------------------------------------------------
46	
47	fn response_with_status<T: Serialize>(status: StatusCode, result: ResultEnvelope<T>) -> Response {
48	    (status, Json(result)).into_response()
49	}
50	
51	fn validation_error(message: &'static str) -> ApiError {
52	    ApiError::new(message, ErrorType::Validation, ErrorContext::Api).with_status(400)
53	}
54	
55	fn internal_500<T: Serialize>() -> Response {
56	    let mut result = ResultEnvelope::<T>::new();
57	    result.add_error(
58	        &ApiError::new(
59	            "Internal server error",
60	            ErrorType::Internal,
61	            ErrorContext::Api,
62	        )
63	        .with_status(500),
64	    );
65	    result.into_response()
66	}
67	
68	/// Stream the cached file honouring `Range` (the `sendFile` surface).
69	async fn send_cached_file(headers: &HeaderMap, path: &FsPath, content_type: &str) -> Response {
70	    let size = match tokio::fs::metadata(path).await {
71	        Ok(meta) => meta.len(),
72	        Err(err) => {
73	            tracing::error!(target: "DEEZER", error = %err, "sendFile stat failed");
74	            return internal_500::<()>();
75	        }
76	    };
77	    let range = headers
78	        .get(header::RANGE)
79	        .and_then(|value| value.to_str().ok());
80	    file_response(
81	        path,
82	        size,
83	        parse_range(range, size),
84	        content_type,
85	        HeaderMap::new(),
86	    )
87	    .await
88	}
89	
90	/// Traducción `AudioServe` -> HTTP: archivo con Range, fallo como envelope
91	/// (el envelope emite status derivado + `x-error-code`/`x-error-type`).
92	async fn serve_outcome(headers: &HeaderMap, outcome: AudioServe) -> Response {
93	    match outcome {
94	        AudioServe::File { path, content_type } => {
95	            send_cached_file(headers, &path, content_type).await
96	        }
97	        AudioServe::Fail(envelope) => envelope.into_response(),
98	    }
99	}
100	
101	// ---------------------------------------------------------------------------
102	// Search-query parsing (deezer-controller.ts:711-748)
103	// ---------------------------------------------------------------------------
104	
105	/// First occurrence of `key` in the raw query string. Mirrors the TS
106	/// `firstString` guard for clients that emit duplicate keys (`?q=a&q=b`).
107	fn query_first(raw: Option<&str>, key: &str) -> Option<String> {
108	    url::form_urlencoded::parse(raw?.as_bytes())
109	        .find(|(k, _)| k == key)
110	        .map(|(_, v)| v.into_owned())
111	}
112	
113	/// `Number.parseInt(s, 10)`: optional sign + leading decimal digits, `None`
114	/// when no digits lead the (trimmed) input.
115	fn parse_int_prefix(raw: &str) -> Option<i64> {
116	    let s = raw.trim_start();
117	    let (negative, rest) = match s.as_bytes().first() {
118	        Some(b'-') => (true, &s[1..]),
119	        Some(b'+') => (false, &s[1..]),
120	        _ => (false, s),
121	    };
122	    let digits = rest
123	        .as_bytes()
124	        .iter()
125	        .take_while(|b| b.is_ascii_digit())
126	        .count();
127	    if digits == 0 {
128	        return None;
129	    }
130	    let magnitude =
131	        rest[..digits]
132	            .parse::<i64>()
133	            .unwrap_or(if negative { i64::MIN } else { i64::MAX });
134	    Some(if negative { -magnitude } else { magnitude })
135	}
136	
137	struct ParsedSearchQuery {
138	    q: String,
139	    limit: i64,
140	    errors: Vec<&'static str>,
141	}
142	
143	fn parse_search_query(raw: Option<&str>) -> ParsedSearchQuery {
144	    let q = normalize_query_text(&query_first(raw, "q").unwrap_or_default());
145	    let limit_raw = query_first(raw, "limit").unwrap_or_default();
146	    // TS: `limitRaw ? parseInt(limitRaw) : NaN`, and NaN selects the default.
147	    let limit = if limit_raw.is_empty() {
148	        None
149	    } else {
150	        parse_int_prefix(&limit_raw)
151	    };
152	
153	    let mut errors = Vec::new();
154	    if q.is_empty() {
155	        errors.push("Query parameter `q` is required");
156	    }
157	    if let Some(limit) = limit {
158	        if !(SEARCH_LIMIT_MIN..=SEARCH_LIMIT_MAX).contains(&limit) {
159	            errors.push("Query parameter `limit` must be between 1 and 25");
160	        }
161	    }
162	
163	    ParsedSearchQuery {
164	        q,
165	        limit: limit.unwrap_or(SEARCH_LIMIT_DEFAULT),
166	        errors,
167	    }
168	}
