170	// ---------------------------------------------------------------------------
171	// Handlers
172	// ---------------------------------------------------------------------------
173	
174	/// `getHealthHandler` — 200 "OK" / 500 "UNAVAILABLE".
175	pub async fn get_health(
176	    State(state): State<AppState>,
177	    bw: Option<Extension<BandwidthOp>>,
178	) -> Response {
179	    let bw = bw.as_ref().map(|extension| &extension.0);
180	    let healthy = state.system.salud(Tipo::Deezer, bw).await;
181	
182	    let mut result = ResultEnvelope::<&'static str>::new();
183	    result.add_data(if healthy { "OK" } else { "UNAVAILABLE" });
184	    if healthy {
185	        result.into_response()
186	    } else {
187	        response_with_status(StatusCode::INTERNAL_SERVER_ERROR, result)
188	    }
189	}
190	
191	/// `getTrackInfoHandler` — `GET /deezer/tracks/{track_id}`.
192	pub async fn get_track_info(
193	    State(state): State<AppState>,
194	    Path(track_id): Path<String>,
195	    bw: Option<Extension<BandwidthOp>>,
196	) -> Response {
197	    let bw = bw.as_ref().map(|extension| &extension.0);
198	    let mut result = ResultEnvelope::<DeezerTrackInfo>::new();
199	    tracing::debug!(target: "DEEZER", track_id, "getTrackInfo controller input");
200	
201	    match state.system.cancion_info(&track_id, bw).await {
202	        Ok(info) => {
203	            tracing::debug!(
204	                target: "DEEZER",
205	                track_id,
206	                isrc = ?info.isrc,
207	                "getTrackInfo controller response"
208	            );
209	            result.add_data(info);
210	            result.into_response()
211	        }
212	        Err(errors) => {
213	            for error in &errors {
214	                result.add_error(error);
215	            }
216	            result.into_response()
217	        }
218	    }
219	}
220	
221	/// `getTrackByIsrcHandler` — `GET /deezer/tracks/by-isrc/{isrc}`.
222	pub async fn get_track_by_isrc(
223	    State(state): State<AppState>,
224	    Path(isrc): Path<String>,
225	    bw: Option<Extension<BandwidthOp>>,
226	) -> Response {
227	    let bw = bw.as_ref().map(|extension| &extension.0);
228	    let mut result = ResultEnvelope::<DeezerTrackInfo>::new();
229	    tracing::debug!(target: "DEEZER", isrc, "getTrackByIsrc controller input");
230	
231	    match state.system.cancion_info_por_isrc(&isrc, bw).await {
232	        Ok(info) => {
233	            tracing::debug!(
234	                target: "DEEZER",
235	                isrc,
236	                deezer_track_id = %info.id,
237	                "getTrackByIsrc controller response"
238	            );
239	            result.add_data(info);
240	            result.into_response()
241	        }
242	        Err(errors) => {
243	            for error in &errors {
244	                result.add_error(error);
245	            }
246	            result.into_response()
247	        }
248	    }
249	}
