/// `getAutocompleteHandler` — `GET /deezer/autocomplete?q&limit`.
pub async fn get_autocomplete(
    State(state): State<AppState>,
    RawQuery(raw): RawQuery,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let mut result = ResultEnvelope::<Value>::new();

    let parsed = parse_search_query(raw.as_deref());
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getAutocomplete controller input"
    );
    if !parsed.errors.is_empty() {
        for message in parsed.errors {
            result.add_error(&validation_error(message));
        }
        return result.into_response();
    }

    let data = state
        .system
        .autocompletar(&parsed.q, Some(parsed.limit as u32), bw)
        .await;
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getAutocomplete controller response"
    );
    result.add_data(data);
    result.into_response()
