340	    /// Caso 3 — tokens de sesión/track (`getTrackTokensHandler`).
341	    pub async fn cancion_tokens(
342	        &self,
343	        track_id: &str,
344	        bw: Option<&BandwidthOp>,
345	    ) -> ResultEnvelope<TrackRawData> {
346	        let mut result = ResultEnvelope::<TrackRawData>::new();
347	        tracing::debug!(target: "DEEZER", track_id, "getTrackTokens controller input");
348	
349	        let context = DeezerArlFailureContext {
350	            track_id: Some(track_id.to_string()),
351	            ..Default::default()
352	        };
353	        let Some(tokens) = self
354	            .deezer
355	            .fetch_session_tokens(false, Some(&context), bw)
356	            .await
357	        else {
358	            result.add_error(
359	                &ApiError::new(
360	                    "Invalid license token in session",
361	                    ErrorType::Internal,
362	                    ErrorContext::Api,
363	                )
364	                .with_status(401),
365	            );
366	            return result;
367	        };
368	
369	        let token_key = deezer_track_token_key(track_id);
370	        let cached_token = match self.redis.get_value(&token_key).await {
371	            Ok(value) => value.and_then(|v| v.as_str().map(str::to_owned)),
372	            Err(error) => {
373	                tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
374	                return internal_500();
375	            }
376	        };
377	        tracing::debug!(
378	            target: "DEEZER",
379	            track_id,
380	            cache_hit = cached_token.is_some(),
381	            "getTrackTokens track token cache"
382	        );
383	
384	        let track_token = match cached_token {
385	            Some(token) => token,
386	            None => {
387	                let song = match self
388	                    .deezer
389	                    .get_song_data(
390	                        &tokens.session_id,
391	                        &tokens.api_token,
392	                        track_id,
393	                        Some(&context),
394	                        bw,
395	                    )
396	                    .await
397	                {
398	                    Ok(song) => song,
399	                    Err(error) => {
400	                        tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
401	                        return internal_500();
402	                    }
403	                };
404	                if song.is_error_license_token {
405	                    tracing::error!(
406	                        target: "DEEZER",
407	                        track_id,
408	                        "DeezerController - getTrack - Invalid license token in song data"
409	                    );
410	                    result.add_error(
411	                        &ApiError::new(
412	                            "Invalid license token in song data",
413	                            ErrorType::Internal,
414	                            ErrorContext::Api,
415	                        )
416	                        .with_status(401),
417	                    );
418	                    return result;
419	                }
420	
421	                let results = song.results.unwrap_or(Value::Null);
422	                let token = results
423	                    .get("TRACK_TOKEN")
424	                    .and_then(Value::as_str)
425	                    .unwrap_or("")
426	                    .to_string();
427	                let track_exp = results.get("TRACK_TOKEN_EXPIRE").and_then(Value::as_i64);
428	                let ttl = token_related_ttl(track_exp);
429	                if let Err(error) = self
430	                    .redis
431	                    .set_value(&token_key, &Value::String(token.clone()), Some(ttl))
432	                    .await
433	                {
434	                    tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrack");
435	                    return internal_500();
436	                }
437	                token
438	            }
439	        };
440	
441	        let data = TrackRawData {
442	            track_id: track_id.to_string(),
443	            track_format: String::new(),
444	            session_id: tokens.session_id,
445	            api_token: tokens.api_token,
446	            license_token: tokens.license_token,
447	            track_token,
448	            track_url: String::new(),
449	        };
450	        tracing::debug!(
451	            target: "DEEZER",
452	            track_id,
453	            has_track_token = !data.track_token.is_empty(),
454	            "getTrackTokens controller response"
455	        );
456	        result.add_data(data);
457	        result
458	    }
