592	    /// Caso 7 — solo-caché con formato explícito (probe, nunca descarga).
593	    pub async fn cancion_archivo_solo_cache(
594	        &self,
595	        track_id: &str,
596	        raw_format: &str,
597	        bw: Option<&BandwidthOp>,
598	    ) -> AudioServe {
