709	    /// Shared tail of the `/file` flows once the target spec is known:
710	    /// fs-cache short-circuit, bounded download-lock orchestration, heartbeat,
711	    /// download pipeline. El frontend hace el streaming del `File` devuelto.
712	    async fn serve_track_file(
713	        &self,
714	        track_id: String,
715	        spec: &'static DeezerFormatSpec,
716	        bw: Option<&BandwidthOp>,
717	    ) -> AudioServe {
718	        let Some(file_path) = self.disk.deezer_cache_path(&track_id, spec.extension) else {
719	            // Defensive: unreachable after the numeric/format validation above.
720	            return AudioServe::Fail(fail_with(&[validation_error("Invalid track format")]));
721	        };
722	        if let Err(error) = validate_directory(&self.disk.deezer).await {
723	            tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
724	            return AudioServe::Fail(internal_500());
725	        }
726	
727	        // Bounded lock acquisition (TS while-loop, 3 attempts, 60 s waits).
728	        let mut attempts = 0u32;
729	        let guard = loop {
730	            match DownloadLock::try_acquire(self.redis.conn(), &track_id, Some(spec.token)).await {
731	                Ok(Some(guard)) => {
732	                    if validate_file(&file_path).await {
733	                        if let Ok(meta) = tokio::fs::metadata(&file_path).await {
734	                            tracing::info!(
735	                                target: "DEEZER",
736	                                track_id,
737	                                origin = "deezer",
738	                                file_size = meta.len(),
739	                                "track file source: fs cache (lock owner)"
740	                            );
741	                        }
742	                        if let Some(op) = bw {
743	                            op.set_provider(BandwidthProvider::Deezer);
744	                            op.mark_cache(CacheMark::Hit);
745	                        }
746	                        release_lock(guard, &track_id).await;
747	                        return AudioServe::File {
748	                            path: file_path,
749	                            content_type: spec.content_type,
750	                        };
751	                    }
752	                    break guard;
753	                }
754	                Ok(None) => {
755	                    attempts += 1;
756	                    if attempts > MAX_LOCK_ATTEMPTS {
757	                        tracing::warn!(
758	                            target: "DEEZER",
759	                            track_id,
760	                            attempts = MAX_LOCK_ATTEMPTS,
761	                            "Download lock contention — giving up after max attempts"
762	                        );
763	                        return AudioServe::Fail(fail_with(&[ApiError::new(
764	                            "Download lock contention; another worker is holding the lock",
765	                            ErrorType::Internal,
766	                            ErrorContext::Api,
767	                        )
768	                        .with_status(503)]));
769	                    }
770	
771	                    let released = match DownloadLock::wait_for(
772	                        self.redis.conn(),
773	                        &track_id,
774	                        LOCK_WAIT_MS,
775	                        Some(spec.token),
776	                    )
777	                    .await
778	                    {
779	                        Ok(released) => released,
780	                        Err(error) => {
781	                            tracing::error!(
782	                                target: "DEEZER",
783	                                error = %error,
784	                                "DeezerController - getTrackFile"
785	                            );
786	                            return AudioServe::Fail(internal_500());
787	                        }
788	                    };
789	                    if validate_file(&file_path).await {
790	                        if let Ok(meta) = tokio::fs::metadata(&file_path).await {
791	                            tracing::info!(
792	                                target: "DEEZER",
793	                                track_id,
794	                                origin = "deezer",
795	                                file_size = meta.len(),
796	                                "track file source: fs cache (peer downloaded)"
797	                            );
798	                        }
799	                        if let Some(op) = bw {
800	                            op.set_provider(BandwidthProvider::Deezer);
801	                            op.mark_cache(CacheMark::Hit);
802	                        }
803	                        return AudioServe::File {
804	                            path: file_path,
805	                            content_type: spec.content_type,
806	                        };
807	                    }
808	                    if !released {
809	                        tracing::warn!(
810	                            target: "DEEZER",
811	                            track_id,
812	                            attempt = attempts,
813	                            "Download lock wait timed out"
814	                        );
815	                    }
816	                }
817	                Err(error) => {
818	                    tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
819	                    return AudioServe::Fail(internal_500());
820	                }
821	            }
822	        };
823	
824	        // Heartbeat + download + cleanup run in a DETACHED task: if the client
825	        // aborts mid-download, hyper drops the caller's future, but the spawned
826	        // task keeps going — it finishes the download (populating the fs cache
827	        // so the retry is a cheap hit), aborts the extender and releases the
828	        // lock. Without the spawn, dropping the future here leaked the extender
829	        // loop, which kept renewing the DownloadLock forever and permanently
830	        // bricked the track. The task itself is bounded by the download's own
831	        // timeouts (60 s overall, 10 s per chunk), so it cannot outlive them.
832	        let task = tokio::spawn({
833	            let system = self.clone();
834	            let track_id = track_id.clone();
835	            let bw = bw.cloned();
836	            async move {
837	                // Heartbeat: extend OUR lock every 15 s while the download runs. A token
838	                // mismatch means a peer took over (e.g. our TTL lapsed during a Redis
839	                // outage) — the script refuses and we log, exactly like the TS extender.
840	                let guard = Arc::new(guard);
841	                let extender = {
842	                    let guard = Arc::clone(&guard);
843	                    let track_id = track_id.clone();
844	                    tokio::spawn(async move {
845	                        let mut tick = tokio::time::interval(LOCK_EXTEND_INTERVAL);
846	                        tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
847	                        tick.tick().await; // interval fires immediately; setInterval does not
848	                        loop {
849	                            tick.tick().await;
850	                            match guard.extend().await {
851	                                Ok(true) => {}
852	                                Ok(false) => tracing::warn!(
853	                                    target: "DEEZER",
854	                                    track_id,
855	                                    "Lock extend refused (token mismatch — peer took over?)"
856	                                ),
857	                                Err(error) => tracing::warn!(
858	                                    target: "DEEZER",
859	                                    track_id,
860	                                    err = %error,
861	                                    "Failed to extend download lock"
862	                                ),
863	                            }
864	                        }
865	                    })
866	                };
867	
868	                tracing::info!(
869	                    target: "DEEZER",
870	                    track_id,
871	                    origin = "deezer",
872	                    "track file source: DEEZER API (downloading)"
873	                );
874	
875	                let outcome = system
876	                    .download_and_serve(&track_id, spec, &file_path, bw.as_ref())
877	                    .await;
878	
879	                // TS `finally`: clearInterval + releaseDownloadLock on every exit path.
880	                extender.abort();
881	                let _ = extender.await;
882	                if let Some(guard) = Arc::into_inner(guard) {
883	                    release_lock(guard, &track_id).await;
884	                }
885	                outcome
886	            }
887	        });
888	        match task.await {
889	            Ok(outcome) => outcome,
890	            Err(join_error) => {
891	                tracing::error!(
892	                    target: "DEEZER",
893	                    track_id,
894	                    error = %join_error,
895	                    "DeezerController - getTrackFile (download task failed)"
896	                );
897	                AudioServe::Fail(internal_500())
898	            }
899	        }
900	    }
901	
902	    /// Cold path of the `/file` flows: track data → download URL → Blowfish
903	    /// pipeline → mp3val gate → manifest + counter. Split out so the caller
904	    /// can run the lock cleanup around every exit.
905	    async fn download_and_serve(
906	        &self,
907	        track_id: &str,
908	        spec: &'static DeezerFormatSpec,
909	        file_path: &FsPath,
910	        bw: Option<&BandwidthOp>,
911	    ) -> AudioServe {
912	        let song_data = match self.deezer.get_track_data(track_id, bw).await {
913	            Ok(data) => data,
914	            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
915	        };
916	
917	        let track_url = match self
918	            .deezer
919	            .get_track_download_url(track_id, spec.deezer_formats, spec.token, bw)
920	            .await
921	        {
922	            Ok(url) => url,
923	            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
924	        };
925	
926	        let track_key = calculate_key(track_id, &self.config.deezer.decryption_key);
927	        let metadata = build_deezer_id3_metadata(
928	            &self.http,
929	            &song_data,
930	            track_id,
931	            &self.config.default_image,
932	        )
933	        .await;
934	
935	        let stats = match download_deezer_track(DownloadParams {
936	            client: self.http.clone(),
937	            url: track_url,
938	            track_key,
939	            final_path: file_path.to_path_buf(),
940	            metadata,
941	            container: Some(spec.container.to_string()),
942	            overall_timeout_ms: Some(DOWNLOAD_OVERALL_TIMEOUT_MS),
943	            chunk_timeout_ms: Some(DOWNLOAD_CHUNK_TIMEOUT_MS),
944	        })
945	        .await
946	        {
947	            Ok(stats) => stats,
948	            Err(error) => {
949	                tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
950	                // Propagate the exact CDN status (403 = ARL no cubre/geo-block,
951	                // 404 = track removed) so api-music surfaces it to Lavalink.
952	                let upstream = match &error {
953	                    DownloadError::HttpStatus(status) => *status,
954	                    _ => 500,
955	                };
956	                let api_error = if upstream == 500 {
957	                    internal_error()
958	                } else {
959	                    ApiError::new(
960	                        format!("Deezer upstream returned HTTP {upstream}"),
961	                        ErrorType::Service,
962	                        ErrorContext::Api,
963	                    )
964	                    .with_status(upstream)
965	                };
966	                return AudioServe::Fail(fail_with(&[api_error]));
967	            }
968	        };
969	
970	        if let Some(op) = bw {
971	            op.set_provider(BandwidthProvider::Deezer);
972	            op.mark_cache(CacheMark::Miss);
973	            op.add_upstream_received(stats.downloaded_bytes);
974	        }
975	
976	        // Validate BEFORE registering the cache entry: a file we end up dropping
977	        // must never be announced in Redis as cached. Only MP3 gets the mp3val
978	        // rewrite; FLAC/MP4 were container-validated by the pipeline already.
979	        if spec.container == "mp3" {
980	            if let Err(fix_error) = fix_file(file_path).await {
981	                let meta = tokio::fs::metadata(file_path).await.ok();
982	                if meta.is_none_or(|m| m.len() == 0) {
983	                    let _ = tokio::fs::remove_file(file_path).await;
984	                    tracing::error!(
985	                        target: "DEEZER",
986	                        track_id,
987	                        err = %fix_error,
988	                        "mp3val left an unusable file — dropped from cache"
989	                    );
990	                    return AudioServe::Fail(fail_with(&[ApiError::new(
991	                        "Downloaded audio failed validation",
992	                        ErrorType::Internal,
993	                        ErrorContext::Api,
994	                    )
995	                    .with_status(502)]));
996	                }
997	                tracing::warn!(
998	                    target: "DEEZER",
999	                    track_id,
1000	                    err = %fix_error,
1001	                    "mp3val failed — serving unverified file"
1002	                );
1003	            }
1004	        }
1005	
1006	        let cache_key = format!("{track_id}{extension}", extension = spec.extension);
1007	        let entry = FileManifestEntry {
1008	            source: Some("deezer".to_string()),
1009	            isrc: song_data
1010	                .get("ISRC")
1011	                .and_then(Value::as_str)
1012	                .map(str::to_owned),
1013	            track_id: Some(track_id.to_string()),
1014	            origin_url: None,
1015	            size: Some(stats.file_size),
1016	            cached_at: Some(chrono::Utc::now().timestamp_millis()),
1017	        };
1018	        if let Err(error) = manifest::set_entry(&self.redis, &cache_key, &entry).await {
1019	            tracing::error!(target: "DEEZER", error = %error, "DeezerController - getTrackFile");
1020	            return AudioServe::Fail(internal_500());
1021	        }
1022	
1023	        tracing::info!(
1024	            target: "DEEZER",
1025	            track_id,
1026	            origin = "deezer",
1027	            file_size = stats.file_size,
1028	            decrypt_ms = stats.decrypt_duration_ms,
1029	            "track file source: DEEZER API (Rust pipeline)"
1030	        );
1031	        // Fire-and-forget: the handle is a spawned task, deliberately detached.
1032	        drop(
1033	            self.api_db
1034	                .fire_and_forget_track_counter(TrackCounterSource::Deezer),
1035	        );
1036	        AudioServe::File {
1037	            path: file_path.to_path_buf(),
1038	            content_type: spec.content_type,
1039	        }
1040	    }
1041	}
