1043	/// ¿Es el outcome un 403 etiquetado `format_rights`? Señal del retry de
1044	/// downgrade — misma condición que el `x-error-code` que emite el envelope.
1045	fn is_format_rights_403(outcome: &AudioServe) -> bool {
1046	    match outcome {
1047	        AudioServe::Fail(envelope) => {
1048	            envelope.derived_status() == 403
1049	                && envelope
1050	                    .errors
1051	                    .iter()
1052	                    .find(|error| !error.code.is_empty())
1053	                    .is_some_and(|error| error.code == "format_rights")
1054	        }
1055	        AudioServe::File { .. } => false,
1056	    }
1057	}
