201	        let mut entries = match tokio::fs::read_dir(dir).await {
202	            Ok(entries) => entries,
203	            Err(_) => continue,
204	        };
205	        while let Ok(Some(entry)) = entries.next_entry().await {
206	            let name = entry.file_name();
207	            if !name.to_string_lossy().ends_with(".tmp") {
208	                continue;
209	            }
