use std::io;
use std::path::{Component, Path, PathBuf};
use std::time::{Duration, SystemTime};

/// Shared on-disk roots used by the Deezer and Chipbot caches.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DiskPaths {
    pub root: PathBuf,
    pub deezer: PathBuf,
    pub chipbot: PathBuf,
}

impl DiskPaths {
    pub fn production() -> Self {
        Self::for_root(PathBuf::from("/mnt/disk-songs"))
    }

    pub fn for_root(root: PathBuf) -> Self {
        Self {
            deezer: root.join("tmp-deezer"),
            chipbot: root.join("tmp-chipbot"),
            root,
        }
    }

    /// Resolve a cache-controller file id without allowing lexical traversal
    /// or existing symlink components to escape the cache root.
    pub fn safe_resolve(&self, source: &str, file_id: &str) -> Option<PathBuf> {
        let base = match source {
            "deezer" => &self.deezer,
            "chipbot" => &self.root,
            _ => return None,
        };
        safe_join(base, file_id)
    }

    pub fn deezer_cache_path(&self, track_id: &str, extension: &str) -> Option<PathBuf> {
        if !is_track_id(track_id) || !is_deezer_extension(extension) {
            return None;
        }
        safe_join(&self.deezer, &format!("{track_id}{extension}"))
    }

    pub fn chipbot_cache_path(&self, isrc: &str, extension: &str) -> Option<PathBuf> {
        let isrc = normalize_isrc(isrc)?;
        if !is_audio_extension(extension) {
            return None;
        }
        safe_join(&self.chipbot, &format!("{isrc}{extension}"))
    }
}

pub fn deezer_cache_path(paths: &DiskPaths, track_id: &str, extension: &str) -> Option<PathBuf> {
    paths.deezer_cache_path(track_id, extension)
}

pub fn chipbot_cache_path(paths: &DiskPaths, isrc: &str, extension: &str) -> Option<PathBuf> {
    paths.chipbot_cache_path(isrc, extension)
}

pub const STALE_TMP_MAX_AGE: Duration = Duration::from_secs(10 * 60);
pub const AUDIO_EXTENSIONS: [&str; 6] = [".mp3", ".webm", ".flac", ".ogg", ".m4a", ".wav"];

pub fn is_track_id(value: &str) -> bool {
    !value.is_empty() && value.bytes().all(|b| b.is_ascii_digit())
}

pub fn normalize_isrc(value: &str) -> Option<String> {
    let normalized = value.trim().to_ascii_uppercase();
    let bytes = normalized.as_bytes();
    if bytes.len() != 12
        || !bytes[..2].iter().all(|byte| byte.is_ascii_uppercase())
        || !bytes[2..5]
            .iter()
            .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit())
        || !bytes[5..].iter().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }
    Some(normalized)
}

pub fn is_audio_extension(extension: &str) -> bool {
    AUDIO_EXTENSIONS.contains(&extension)
}

pub fn is_deezer_extension(extension: &str) -> bool {
    matches!(extension, ".mp3" | ".flac" | ".m4a")
}

pub fn audio_content_type(extension: &str) -> &'static str {
    match extension {
        ".mp3" => "audio/mpeg",
        ".webm" => "audio/webm",
        ".flac" => "audio/flac",
        ".ogg" => "audio/ogg",
        ".m4a" => "audio/mp4",
        ".wav" => "audio/wav",
        _ => "audio/mpeg",
    }
}

pub fn resolve_audio_content_type(path: &Path) -> &'static str {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| audio_content_type(&format!(".{ext}")))
        .unwrap_or("audio/mpeg")
}

/// Lexically normalize a relative path and reject traversal and symlink
/// components. Missing final components are allowed for download targets.
pub fn safe_join(base: &Path, relative: &str) -> Option<PathBuf> {
    let relative = Path::new(relative);
    if relative.is_absolute() {
        return None;
    }

    let mut result = base.to_path_buf();
    for component in relative.components() {
        match component {
            Component::Normal(part) => result.push(part),
            Component::CurDir => {}
            Component::ParentDir | Component::RootDir | Component::Prefix(_) => return None,
        }
    }

    // `symlink_metadata` does not follow links. Check every existing component
    // so a path such as `cache/link/escape.mp3` cannot leave the cache root.
    let mut current = PathBuf::new();
    for component in result.components() {
        current.push(component.as_os_str());
        if let Ok(metadata) = std::fs::symlink_metadata(&current) {
            if metadata.file_type().is_symlink() {
                return None;
            }
        }
    }
    Some(result)
}

pub async fn validate_file(path: &Path) -> bool {
    tokio::fs::symlink_metadata(path)
        .await
        .map(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        .unwrap_or(false)
}

pub async fn validate_directory(path: &Path) -> io::Result<()> {
    match tokio::fs::symlink_metadata(path).await {
        Ok(metadata) if metadata.file_type().is_symlink() => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "path is a symlink",
        )),
        Ok(metadata) if metadata.is_dir() => Ok(()),
        Ok(_) => Err(io::Error::new(
            io::ErrorKind::AlreadyExists,
            format!("the specified path is not a directory: {}", path.display()),
        )),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            tokio::fs::create_dir_all(path).await
        }
        Err(error) => Err(error),
    }
}

/// Run the same forced `mp3val` repair used by the TypeScript controller.
pub async fn fix_file(path: &Path) -> io::Result<()> {
    let metadata = tokio::fs::symlink_metadata(path).await?;
    if metadata.file_type().is_symlink() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "path is a symlink",
        ));
    }
    let output = tokio::process::Command::new("mp3val")
        .arg(path)
        .arg("-f")
        .arg("-nb")
        .output()
        .await?;
    if output.status.success() {
        Ok(())
    } else {
        Err(io::Error::other(
            String::from_utf8_lossy(&output.stderr).trim().to_string(),
        ))
    }
}

pub async fn sweep_stale_tmp_files(dirs: &[PathBuf]) -> u64 {
    sweep_stale_tmp_files_with_age(dirs, STALE_TMP_MAX_AGE).await
}

pub async fn sweep_stale_tmp_files_with_age(dirs: &[PathBuf], max_age: Duration) -> u64 {
    let cutoff = SystemTime::now()
        .checked_sub(max_age)
        .unwrap_or(SystemTime::UNIX_EPOCH);
    let mut removed = 0;

    for dir in dirs {
        let mut entries = match tokio::fs::read_dir(dir).await {
            Ok(entries) => entries,
            Err(_) => continue,
        };
        while let Ok(Some(entry)) = entries.next_entry().await {
            let name = entry.file_name();
            if !name.to_string_lossy().ends_with(".tmp") {
                continue;
            }
            if !matches!(entry.file_type().await, Ok(file_type) if file_type.is_file()) {
                continue;
            }
            let metadata = match entry.metadata().await {
                Ok(metadata) => metadata,
                Err(_) => continue,
            };
            let stale = metadata
                .modified()
                .map(|mtime| mtime < cutoff)
                .unwrap_or(false);
            if stale && tokio::fs::remove_file(entry.path()).await.is_ok() {
                removed += 1;
            }
        }
    }
    removed
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::TempDir;

    #[test]
    fn paths_and_validation_match_cache_layout() {
        let root = PathBuf::from("/tmp/music");
        let paths = DiskPaths::for_root(root.clone());
        assert_eq!(paths.deezer, root.join("tmp-deezer"));
        assert_eq!(paths.chipbot, root.join("tmp-chipbot"));
        assert_eq!(
            paths.deezer_cache_path("123", ".mp3"),
            Some(root.join("tmp-deezer/123.mp3"))
        );
        assert!(paths.deezer_cache_path("../123", ".mp3").is_none());
        assert_eq!(
            paths.chipbot_cache_path("usat29900609", ".mp3"),
            Some(root.join("tmp-chipbot/USAT29900609.mp3"))
        );
        assert_eq!(
            normalize_isrc("USAT29900609"),
            Some("USAT29900609".to_string())
        );
        assert_eq!(audio_content_type(".m4a"), "audio/mp4");
    }

    #[tokio::test]
    async fn sweeps_only_old_tmp_files() {
        let dir = TempDir::new().unwrap();
        let stale = dir.path().join("old.tmp");
        let fresh = dir.path().join("new.tmp");
        let cache = dir.path().join("song.mp3");
        fs::write(&stale, b"x").unwrap();
        fs::write(&fresh, b"x").unwrap();
        fs::write(&cache, b"x").unwrap();
        let old = SystemTime::now() - Duration::from_secs(5);
        let file = fs::File::options().write(true).open(&stale).unwrap();
        file.set_modified(old).unwrap();
        assert_eq!(
            sweep_stale_tmp_files_with_age(&[dir.path().to_path_buf()], Duration::from_secs(1))
                .await,
            1
        );
        assert!(!stale.exists());
        assert!(fresh.exists());
        assert!(cache.exists());
    }
}

//! Shared application state.
//!
//! Assembled once in `run()` after `Config::load` succeeds and every
//! backing client connects. Handlers receive it via `axum::extract::State`;
//! all fields are cheap to clone (Arc-backed or pooled clients).
//!
//! Provider services are constructed from these primitives in `run()`.

use std::sync::Arc;

use crate::audio::disk::DiskPaths;
use crate::cache::MusicNodoRedis;
use crate::clients::ApiDbClient;
use crate::config::Config;
use crate::providers::chipbot::ChipbotService;
use crate::providers::deezer::DeezerService;
use crate::providers::isrc::IsrcService;
use crate::providers::radio::RadioService;
use crate::providers::spotify::SpotifyService;
use crate::system::MusicSystem;
use crate::telemetry::BandwidthRuntime;

#[derive(Clone)]
pub struct AppState {
    pub config: Arc<Config>,
    /// Núcleo orquestador (providers + políticas transversales). Los
    /// handlers deben ir SIEMPRE a través de él; los campos de provider
    /// que siguen debajo son transitorios hasta completar la Fase 2 del
    /// refactor (ver docs/PLAN_REFACTOR.md).
    pub system: MusicSystem,
    /// Shared pooled HTTP client (upstream calls: Deezer, Spotify, radio,
    /// chipbot, Infisical). One client per process, HTTP/2 reuse.
    pub http: reqwest::Client,
    /// Redis DB 7 cache handle (codec-compatible with the TS client).
    pub redis: MusicNodoRedis,
    /// Typed api-db client (ARLs, track counter, track errors).
    pub api_db: ApiDbClient,
    /// Bandwidth telemetry runtime (store + background flush task).
    pub bandwidth: BandwidthRuntime,
    /// Disk cache roots under `/mnt/disk-songs`.
    pub disk: DiskPaths,
    /// Deezer provider (sessions, search, downloads) + its `ArlManager`.
    pub deezer: DeezerService,
    /// Spotify partner-API provider.
    pub spotify: SpotifyService,
    /// Radio Garden provider.
    pub radio: RadioService,
    /// Chipbot fallback provider.
    pub chipbot: ChipbotService,
    /// ISRC lookup provider (tools4music/groover/findmy race). Also the
    /// `IsrcResolver` implementation injected into `spotify`.
    pub isrc: Arc<IsrcService>,
}

