/// The single-range forms accepted by the TypeScript send-file helper.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RangeOutcome {
    Full,
    Bounded { start: u64, end: u64 },
    Open { start: u64, end: u64 },
    Suffix { start: u64, end: u64 },
    Unsatisfiable { size: u64 },
}

impl RangeOutcome {
    pub fn status(self) -> StatusCode {
        match self {
            Self::Full => StatusCode::OK,
            Self::Bounded { .. } | Self::Open { .. } | Self::Suffix { .. } => {
                StatusCode::PARTIAL_CONTENT
            }
            Self::Unsatisfiable { .. } => StatusCode::RANGE_NOT_SATISFIABLE,
        }
    }

    fn span(self) -> Option<(u64, u64)> {
        match self {
            Self::Bounded { start, end }
            | Self::Open { start, end }
            | Self::Suffix { start, end } => Some((start, end)),
            Self::Full | Self::Unsatisfiable { .. } => None,
        }
    }
}

