//! Núcleo del sistema: `MusicSystem`, un ORQUESTADOR.
//!
//! `MusicSystem` no implementa lógica de ningún proveedor ni de ningún
//! protocolo: recibe peticiones (`MusicQuery` o métodos tipados), decide qué
//! provider(s) atienden, aplica las políticas transversales (caché Redis,
//! locks de descarga, disco, telemetría de bandwidth, contador de tracks) y
//! compone el resultado. Los providers ejecutan; los frontends traducen.
//!
//! Regla de frontera: este módulo NUNCA importa tipos de frontend (`axum`,
//! status codes, headers). Un frontend nuevo (gRPC/WS/cola) se añade como
//! módulo hermano de `src/http/` hablando sólo `MusicQuery`/`MusicOutcome`.

pub mod deezer_files;
pub mod query;
pub mod result;

use std::sync::Arc;

use serde_json::Value;

use crate::audio::disk::DiskPaths;
use crate::cache::MusicNodoRedis;
use crate::clients::ApiDbClient;
use crate::config::Config;
use crate::providers::chipbot::ChipbotService;
use crate::providers::deezer::{DeezerResult, DeezerService, DeezerTrackInfo};
use crate::providers::isrc::{IsrcError, IsrcService};
use crate::providers::radio::{RadioSearchHit, RadioService, RadioStation};
use crate::providers::spotify::{
    SpotifyError, SpotifyPlaylistSnapshot, SpotifyPlaylistWithTracks, SpotifyService, SpotifyTrack,
};
use crate::telemetry::{BandwidthOp, BandwidthRuntime};

pub use query::{MusicQuery, Necesito, Pedir, Tipo};
pub use result::{AudioServe, MusicOutcome};

/// Piezas con las que se ensambla el sistema (construidas en `app::run`).
/// Struct en vez de 11 argumentos posicionales: los campos se nombran.
pub struct MusicSystemParts {
    pub config: Arc<Config>,
    pub http: reqwest::Client,
    pub redis: MusicNodoRedis,
    pub api_db: ApiDbClient,
    pub bandwidth: BandwidthRuntime,
    pub disk: DiskPaths,
    pub deezer: DeezerService,
    pub spotify: SpotifyService,
    pub radio: RadioService,
    pub chipbot: ChipbotService,
    pub isrc: Arc<IsrcService>,
}

/// El orquestador. Clonable barato (todo Arc/pool por dentro).
#[derive(Clone)]
pub struct MusicSystem {
    config: Arc<Config>,
    http: reqwest::Client,
    redis: MusicNodoRedis,
    api_db: ApiDbClient,
    bandwidth: BandwidthRuntime,
    disk: DiskPaths,
    deezer: DeezerService,
    spotify: SpotifyService,
    radio: RadioService,
    chipbot: ChipbotService,
    isrc: Arc<IsrcService>,
}

impl MusicSystem {
    pub fn new(parts: MusicSystemParts) -> Self {
        Self {
            config: parts.config,
            http: parts.http,
            redis: parts.redis,
            api_db: parts.api_db,
            bandwidth: parts.bandwidth,
            disk: parts.disk,
            deezer: parts.deezer,
            spotify: parts.spotify,
            radio: parts.radio,
            chipbot: parts.chipbot,
            isrc: parts.isrc,
        }
    }

    /// Runtime de telemetría — lo necesita el middleware de contexto de
    /// bandwidth del frontend HTTP para finalizar cada operación.
    pub fn bandwidth(&self) -> &BandwidthRuntime {
        &self.bandwidth
    }

    // -----------------------------------------------------------------
    // pedir: cancion / necesito: informacion
    // -----------------------------------------------------------------

    /// Caso 1 — Deezer: información por ID.
    pub async fn cancion_info(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> DeezerResult<DeezerTrackInfo> {
        self.deezer.get_track_info(track_id, bw).await
    }

    /// Caso 2 — Deezer: información por ISRC.
    pub async fn cancion_info_por_isrc(
        &self,
        isrc: &str,
        bw: Option<&BandwidthOp>,
    ) -> DeezerResult<DeezerTrackInfo> {
        self.deezer.get_track_by_isrc(isrc, bw).await
    }

    /// Caso 10 — Spotify: información de track.
    pub async fn spotify_cancion_info(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyTrack>, SpotifyError> {
        self.spotify.get_track(track_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: autocompletado / busqueda
    // -----------------------------------------------------------------

    /// Caso 12 — Deezer: autocompletado de canciones.
    pub async fn autocompletar(
        &self,
        q: &str,
        limit: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Value {
        self.deezer.get_autocomplete(q, limit, bw).await
    }

    /// Caso 13 — Deezer: búsqueda de canciones.
    pub async fn buscar_canciones(
        &self,
        q: &str,
        limit: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Value {
        self.deezer.get_search_route(q, limit, bw).await
    }

    /// Caso 14 — Radio: búsqueda de canales.
    pub async fn buscar_canales(&self, q: &str, bw: Option<&BandwidthOp>) -> Vec<RadioSearchHit> {
        self.radio.search(q, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: canal / playlist
    // -----------------------------------------------------------------

    /// Caso 15 — Radio: información de canal.
    pub async fn canal_info(
        &self,
        channel_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Option<RadioStation> {
        self.radio.get_channel(channel_id, bw).await
    }

    /// Caso 16 — Spotify: información de playlist (paginada).
    pub async fn playlist_info(
        &self,
        playlist_id: &str,
        limit: Option<u32>,
        offset: Option<u32>,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyPlaylistWithTracks>, SpotifyError> {
        self.spotify.get_playlist(playlist_id, limit, offset, bw).await
    }

    /// Caso 17 — Spotify: snapshot de playlist.
    pub async fn playlist_snapshot(
        &self,
        playlist_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<SpotifyPlaylistSnapshot>, SpotifyError> {
        self.spotify.get_playlist_snapshot(playlist_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: isrc
    // -----------------------------------------------------------------

    /// Casos 11 y 18 — ISRC de un track (carrera de proveedores dedicada;
    /// la ruta de Spotify usa el mismo servicio).
    pub async fn resolver_isrc(
        &self,
        track_id: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<String>, IsrcError> {
        self.isrc.get_isrc(track_id, bw).await
    }

    // -----------------------------------------------------------------
    // pedir: salud
    // -----------------------------------------------------------------

    /// Casos 20-23 — salud por tipo. `Sistema` es la vivacidad del propio
    /// proceso (siempre `true` si responde). Radio es hoy un stub que
    /// devuelve `true` sin sondear (paridad TS) — el gap 6 del catálogo lo
    /// cablea al probe real en la Fase 3 del refactor.
    pub async fn salud(&self, tipo: Tipo, bw: Option<&BandwidthOp>) -> bool {
        match tipo {
            Tipo::Deezer => self.deezer.health(bw).await,
            Tipo::Spotify => self.spotify.health(bw).await,
            Tipo::Radio => true,
            Tipo::Chipbot => self.chipbot.health(bw).await.ok,
            Tipo::IsrcService => self.isrc.health(bw).await,
            Tipo::Sistema => true,
        }
    }
}

