//! Modelo `pedir / tipo / necesito` — el vocabulario con el que cualquier
//! frontend (HTTP hoy; gRPC/WS/cola mañana) le pide cosas al sistema.
//!
//! Es la forma tipada del catálogo `docs/CASOS_DE_USO.md`: cada caso es una
//! combinación `(pedir, tipo, necesito)` + parámetros. El dispatcher
//! `MusicSystem::resolve` hace match exhaustivo sobre estas combinaciones;
//! las no soportadas devuelven un fallo de validación, nunca un panic.
//!
//! Nota de frontera: la especificación OpenAPI (caso 24 del catálogo) NO
//! está aquí a propósito — documenta la superficie HTTP, así que pertenece
//! al frontend HTTP (`src/http/openapi.rs`), no al núcleo.

use serde::{Deserialize, Serialize};

/// Qué se pide.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Pedir {
    Cancion,
    Autocompletado,
    Busqueda,
    Canal,
    Playlist,
    Isrc,
    Cache,
    Salud,
}

/// A qué proveedor (o al propio sistema) se le pide.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Tipo {
    Deezer,
    Spotify,
    Radio,
    Chipbot,
    /// Servicio dedicado de resolución ISRC (carrera tools4music/groover/findmy).
    #[serde(rename = "isrc")]
    IsrcService,
    Sistema,
}

/// Qué se necesita del recurso pedido.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Necesito {
    Informacion,
    Archivo,
    ArchivoSoloCache,
    Tokens,
    FormatosDisponibles,
    Canciones,
    Canales,
    Snapshot,
    Isrc,
    Eliminar,
    Estado,
}

/// Una petición completa al sistema.
///
/// Los parámetros opcionales sólo aplican a algunas combinaciones:
/// `formato` a `necesito: archivo`, `q`/`limit` a autocompletado/búsqueda,
/// `offset`/`limit` a playlists, `id` a todo lo que referencia un recurso
/// concreto (track_id, ISRC, channel_id, playlist_id, id de caché).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MusicQuery {
    pub pedir: Pedir,
    pub tipo: Tipo,
    pub necesito: Necesito,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub formato: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub q: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub limit: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub offset: Option<u32>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn query_roundtrips_from_the_wire_shape() {
        let raw = serde_json::json!({
            "pedir": "cancion",
            "tipo": "deezer",
            "necesito": "archivo",
            "formato": "flac",
            "id": "3135556"
        });
        let query: MusicQuery = serde_json::from_value(raw).expect("deserialize");
        assert_eq!(query.pedir, Pedir::Cancion);
        assert_eq!(query.tipo, Tipo::Deezer);
        assert_eq!(query.necesito, Necesito::Archivo);
        assert_eq!(query.formato.as_deref(), Some("flac"));
        assert_eq!(query.q, None);
    }

    #[test]
    fn kebab_case_variants_match_the_catalog() {
        assert_eq!(
            serde_json::to_value(Necesito::ArchivoSoloCache).unwrap(),
            serde_json::json!("archivo-solo-cache")
        );
        assert_eq!(
            serde_json::to_value(Necesito::FormatosDisponibles).unwrap(),
            serde_json::json!("formatos-disponibles")
        );
        assert_eq!(
            serde_json::to_value(Tipo::IsrcService).unwrap(),
            serde_json::json!("isrc")
        );
    }
}

//! File-manifest cache (`files:cache:<filename>` hashes).
//!
//! Port of `libraries/library-shared/src/redis/cache/file-manifest/`
//! (`FileManifestCache`). Entries describe one cached audio file on disk;
//! api-music reads the same hashes, so field names and codec behavior are
//! wire-frozen.

