use serde_json::Value;

use super::keys::file_manifest_key;
use super::MusicNodoRedis;

/// `FileManifestEntry` in file-manifest-cache.ts. All fields are optional on
/// read (a hash written by an older producer may miss keys); `set_entry`
/// skips `None` fields exactly like the TS `sanitized` loop drops
/// `undefined`/`null`.
///
/// Note: numeric-looking strings (e.g. `track_id`) round-trip through the
/// codec as JSON numbers, so readers coerce via [`value_as_string`].
#[derive(Debug, Clone, Default, PartialEq)]
pub struct FileManifestEntry {
    pub source: Option<String>,
    pub isrc: Option<String>,
    pub track_id: Option<String>,
