//! Port of `chipbot-controller.ts` (Chipbot cached-audio routes).
//!
//! Adaptador fino: la orquestación de archivos (validación ISRC/formato,
//! probe de fs-cache, descarga tmp+rename, ID3, manifiesto y contador) vive
//! en `crate::system::chipbot_files`; aquí solo queda la traducción HTTP —
//! Range (RFC 7233) sobre el `AudioServe::File` que devuelve el núcleo, y el
//! mapeo de `Err(String)` a un 500 con `cause`, con el nombre del handler en
//! el log.

use std::path::Path as FsPath;

use axum::extract::{Extension, Path, State};
use axum::http::{header, HeaderMap};
use axum::response::{IntoResponse, Response};

use crate::audio::{file_response, parse_range};
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::state::AppState;
use crate::system::AudioServe;
use crate::telemetry::BandwidthOp;

fn internal_error_response(cause: String) -> Response {
    let mut error = ApiError::new(
        "Internal server error",
        ErrorType::Internal,
        ErrorContext::Api,
    )
    .with_status(500);
    error = error.with_cause(cause);
    let mut result = ResultEnvelope::<()>::new();
    result.add_error(&error);
    result.into_response()
}

/// Stream the cached file honouring `Range` (the `sendFile` surface).
async fn send_cached_file(headers: &HeaderMap, path: &FsPath, content_type: &str) -> Response {
    let size = match tokio::fs::metadata(path).await {
        Ok(meta) => meta.len(),
        Err(error) => {
            tracing::error!(target: "CHIPBOT", error = %error, "sendFile stat failed");
            return internal_error_response(format!("stat cached Chipbot file: {error}"));
        }
    };
    let range = headers
        .get(header::RANGE)
        .and_then(|value| value.to_str().ok());
    file_response(
        path,
        size,
        parse_range(range, size),
        content_type,
        HeaderMap::new(),
    )
    .await
}

/// Traducción `AudioServe` -> HTTP: archivo con Range, fallo como envelope
/// (el envelope emite status derivado + `x-error-code`/`x-error-type`).
async fn serve_outcome(headers: &HeaderMap, outcome: AudioServe) -> Response {
    match outcome {
        AudioServe::File { path, content_type } => {
            send_cached_file(headers, &path, content_type).await
        }
        AudioServe::Fail(envelope) => envelope.into_response(),
    }
}

/// `getTrackFileByIsrcHandler` — downloads on cache miss.
pub async fn get_track_file_by_isrc(
    State(state): State<AppState>,
    Path((raw_isrc, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    match state.system.chipbot_archivo(&raw_isrc, &raw_format, bw).await {
        Ok(outcome) => serve_outcome(&headers, outcome).await,
        Err(error) => {
            tracing::error!(
                target: "CHIPBOT",
                error,
                "ChipbotController - getTrackFileByIsrc"
            );
            internal_error_response(error)
        }
    }
}

